        Question(9572, "Quel fleuve est la frontière entre la Thaïlande et le Laos?", listOf("Salouen", "Nam Ou", "Mékong", "Nam Tha"), 2, "Géographie", Difficulty.HARD, explanation = "Le Mékong forme une frontière naturelle sur plus de 1 800 kilomètres entre la Thaïlande et le Laos."),
        Question(9573, "La capitale de la Mongolie est...", listOf("Darkhan", "Erdenet", "Oulan-Bator", "Choibalsan"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Oulan-Bator, signifiant \"Héros rouge\", est la capitale et la plus grande ville de Mongolie, abritant près de la moitié de la population du pays."),
        Question(9574, "Quel océan entoure le Japon?", listOf("Mer de Chine", "Océan Pacifique", "Mer de l'Est", "Golfe du Bengale"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Japon est un archipel situé dans l'océan Pacifique, qui borde sa côte est et sud."),
        Question(9575, "La capitale de la Corée du Nord est...", listOf("Hamhung", "Wonsan", "Pyongyang", "Kaesong"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Pyongyang est la capitale et la plus grande ville de la Corée du Nord, située sur le fleuve Taedong."),
        Question(9576, "Quel est le plus grand lagon du monde?", listOf("Lagon de Bora Bora", "Lagon de Rangiroa", "Atolls des Tuamotu", "Grand lagon de Nouvelle-Calédonie"), 2, "Géographie", Difficulty.EXPERT, explanation = "Les Tuamotu, en Polynésie française, forment le plus vaste ensemble d'atolls et de lagons du monde, avec une superficie de lagon estimée à plus de 15 000 km²."),
        Question(9577, "La capitale de la Corée du Sud est...", listOf("Busan", "Incheon", "Séoul", "Gwangju"), 2, "Géographie", Difficulty.EASY, explanation = "Séoul est la capitale de la Corée du Sud depuis la création de la République en 1948, et elle constitue le centre politique, économique et culturel du pays."),
        Question(9578, "Quel est le point le plus bas du monde?", listOf("Canyon Mariana", "Lac Baïkal", "Mer Morte", "Dépression de Turpan"), 2, "Géographie", Difficulty.HARD, explanation = "La Mer Morte, située entre Israël, la Jordanie et la Cisjordanie, se trouve à environ 430 mètres sous le niveau de la mer, ce qui en fait la dépression la plus profonde de la planète."),
        Question(9579, "La capitale de Taiwan est...", listOf("Kaohsiung", "Taichung", "Taipei", "Tainan"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Taipei est le siège du gouvernement de la République de Chine (Taïwan) depuis 1949."),
        Question(9580, "Quel continent a le plus de fuseaux horaires?", listOf("Asie", "Amérique du Nord", "Europe", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord inclut le Groenland et les territoires insulaires éloignés comme Hawaï, ce qui lui donne 11 fuseaux horaires, soit le plus grand nombre pour un continent."),
        Question(9581, "La capitale du Bangladesh est...", listOf("Chittagong", "Khulna", "Dacca", "Sylhet"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Dacca est la capitale et la plus grande ville du Bangladesh, située au centre du pays sur les rives de la rivière Buriganga."),
        Question(9582, "Quel est le plus grand récif corallien du monde?", listOf("Récif de Ningaloo", "Récif d'Andros", "Grande Barrière de Corail", "Récif de Toau"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace, ce qui en fait le plus vaste écosystème corallien de la planète."),
        Question(9583, "La capitale du Pakistan est...", listOf("Karachi", "Lahore", "Islamabad", "Multan"), 2, "Géographie", Difficulty.EASY, explanation = "Islamabad est devenue la capitale du Pakistan en 1963, remplaçant Karachi, pour des raisons de centralisation géographique et de développement planifié."),
        Question(9584, "Quel fleuve traverse l'Inde?", listOf("Indus", "Gange", "Brahmapoutre", "Tous les trois"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le Gange, l'Indus et le Brahmapoutre sont les trois principaux fleuves qui traversent l'Inde, chacun jouant un rôle crucial dans la géographie et la culture du pays."),
        Question(9585, "La capitale de l'Afghanistan est...", listOf("Kandahar", "Mazar-i-Charif", "Kaboul", "Herat"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Kaboul est la plus grande ville d'Afghanistan et son centre politique, économique et culturel depuis le XVIIIe siècle."),
        Question(9586, "Quel est le plus grand pays du Moyen-Orient?", listOf("Arabie Saoudite", "Iran", "Irak", "Yémen"), 1, "Géographie", Difficulty.HARD, explanation = "L'Arabie saoudite est souvent considérée comme le plus grand pays du Moyen-Orient, mais l'Iran le dépasse légèrement en superficie si l'on inclut l'ensemble de son territoire."),
        Question(9587, "La capitale de l'Iran est...", listOf("Ispahan", "Tabriz", "Téhéran", "Qom"), 2, "Géographie", Difficulty.EASY, explanation = "Téhéran est la capitale et la plus grande ville de l'Iran, située au nord du pays, au pied des monts Elbourz."),
        Question(9588, "Quel océan borde l'Iran?", listOf("Golfe Persique et Mer Caspienne", "Océan Indien", "Mer d'Arabie", "Golfe d'Oman"), 0, "Géographie", Difficulty.HARD, explanation = "L'Iran possède deux façades maritimes distinctes : la mer Caspienne au nord et le golfe Persique au sud, ce dernier étant une mer marginale de l'océan Indien."),
        Question(9589, "La capitale de l'Irak est...", listOf("Bassora", "Kirkouk", "Bagdad", "Mossoul"), 2, "Géographie", Difficulty.EASY, explanation = "Bagdad est la capitale et la plus grande ville d'Irak, située sur les rives du Tigre. Elle est le centre politique, économique et culturel du pays depuis sa fondation au VIIIe siècle."),
        Question(9590, "Quel fleuve traverse l'Irak?", listOf("Jourdain", "Tigre et Euphrate", "Oronte", "Litani"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Tigre et l'Euphrate traversent l'Irak, formant la Mésopotamie, berceau de civilisations antiques."),
        Question(9591, "La capitale de la Syrie est...", listOf("Alep", "Lattaquié", "Damas", "Homs"), 2, "Géographie", Difficulty.EASY, explanation = "Damas est l'une des plus anciennes villes habitées en continu au monde et est le centre politique et culturel de la Syrie depuis des siècles."),
        Question(9592, "Quel est le plus grand désert du Moyen-Orient?", listOf("Négev", "Sinaï", "Désert de Rub' al Khali", "Désert du Nefoud"), 2, "Géographie", Difficulty.HARD, explanation = "Le Rub' al Khali, aussi appelé le Quart Vide, couvre environ 650 000 km² dans la péninsule arabique, ce qui en fait le plus grand désert de sable continu du Moyen-Orient."),
        Question(9593, "La capitale du Liban est...", listOf("Tripoli", "Beyrouth", "Sidon", "Tyr"), 1, "Géographie", Difficulty.EASY, explanation = "Beyrouth est la capitale et la plus grande ville du Liban, située sur la côte méditerranéenne."),
        Question(9594, "Quel est le lac le plus salé du monde?", listOf("Mer Morte", "Lac d'Aral", "Grand Lac Salé", "Mer Caspienne"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La Mer Morte, bordée par Israël et la Jordanie, a une salinité d'environ 34%, soit près de dix fois celle des océans, ce qui en fait le plan d'eau le plus salé du monde."),
        Question(9595, "La capitale de la Jordanie est...", listOf("Irbid", "Zarqa", "Amman", "Mafraq"), 2, "Géographie", Difficulty.EASY, explanation = "Amman est la capitale et la plus grande ville de Jordanie, située dans le nord-ouest du pays. Elle est le centre politique, économique et culturel du royaume hachémite."),
        Question(9596, "Quel est le plus grand désert d'Asie du Ouest?", listOf("Gobi", "Kyzyl-Koum", "Rub' al Khali", "Kara-Koum"), 2, "Géographie", Difficulty.HARD, explanation = "Le Rub' al Khali, aussi appelé le Quart Vide, s'étend sur une grande partie de la péninsule Arabique, principalement en Arabie saoudite, au Yémen et à Oman, ce qui en fait le plus vaste désert de sable d'Asie de l'Ouest."),
        Question(9597, "La capitale d'Israël est...", listOf("Tel Aviv", "Jérusalem", "Haïfa", "Jaffa"), 1, "Géographie", Difficulty.EASY, explanation = "Jérusalem est la capitale d'Israël depuis 1950, et le siège de ses institutions gouvernementales, bien que ce statut ne soit pas reconnu par une partie de la communauté internationale."),
        Question(9598, "Quel montagnes abritent le Cèdre du Liban?", listOf("Chaîne côtière", "Anti-Liban", "Monts Liban", "Monts Hermon"), 2, "Géographie", Difficulty.HARD, explanation = "Le Cèdre du Liban, symbole national du pays, pousse naturellement dans la chaîne des Monts Liban, où il bénéficie d’un climat méditerranéen d’altitude."),
        Question(9599, "La capitale de l'Arabie Saoudite est...", listOf("Djeddah", "Médine", "Riyad", "Dammam"), 2, "Géographie", Difficulty.EASY, explanation = "Riyad est la capitale et la plus grande ville d'Arabie Saoudite, située au centre du pays sur le plateau du Najd."),
        Question(9600, "Quel est le plus grand pays de la Péninsule Arabique?", listOf("Yémen", "Oman", "Arabie Saoudite", "Émirats"), 2, "Géographie", Difficulty.HARD, explanation = "L'Arabie Saoudite est le plus grand pays de la Péninsule Arabique, couvrant environ 80 % de sa superficie totale."),
        Question(9601, "La capitale des Émirats Arabes Unis est...", listOf("Dubaï", "Charm el-Cheikh", "Abou Dabi", "Charja"), 2, "Géographie", Difficulty.EASY, explanation = "Abou Dabi est la capitale politique et administrative des Émirats Arabes Unis, abritant le siège du gouvernement fédéral et la résidence du président."),
        Question(9602, "Quel océan borde les Émirats Arabes Unis?", listOf("Océan Indien", "Golfe Persique", "Mer d'Arabie", "Golfe d'Oman"), 1, "Géographie", Difficulty.HARD, explanation = "Les Émirats Arabes Unis sont situés sur la péninsule arabique, bordés au nord par le golfe Persique, qui est une mer marginale de l'océan Indien."),
        Question(9603, "La capitale du Qatar est...", listOf("Al Wakrah", "Al Rayyan", "Doha", "Dukhan"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Doha est la capitale et la plus grande ville du Qatar, située sur la côte est de la péninsule qatarie."),
        Question(9604, "Quel est le plus petit pays du Moyen-Orient?", listOf("Bahreïn", "Qatar", "Koweït", "Liban"), 0, "Géographie", Difficulty.HARD, explanation = "Bahreïn est un archipel situé dans le golfe Persique, avec une superficie d'environ 760 km², ce qui en fait le plus petit État souverain du Moyen-Orient."),
        Question(9605, "La capitale de Bahreïn est...", listOf("Riffa", "Al Manama", "Manama", "Sitra"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Manama est la capitale et la plus grande ville de Bahreïn, située sur la côte nord de l'île de Bahreïn, dans le golfe Persique."),
        Question(9606, "Quel est le point culminant du Moyen-Orient?", listOf("Pic Damavand", "Mont Ararat", "Pic Zard Kuh", "Mont Hadj"), 0, "Géographie", Difficulty.HARD, explanation = "Le Pic Damavand, situé en Iran, est un volcan endormi culminant à 5 610 mètres, ce qui en fait le plus haut sommet du Moyen-Orient."),
        Question(9607, "La capitale du Koweït est...", listOf("Jahra", "Ahmadi", "Koweit City", "Salimiya"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Koweït City est la capitale et la plus grande ville du Koweït, située sur la côte du golfe Persique. Elle concentre la majorité de la population et des institutions du pays."),
        Question(9608, "Quel fleuve borde l'Égypte au sud?", listOf("Bahr el-Ghazal", "Sobat", "Atbarah", "Nil"), 3, "Géographie", Difficulty.HARD, explanation = "Le Nil traverse l'Égypte du sud au nord, formant sa frontière méridionale avec le Soudan avant de se jeter dans la Méditerranée."),
        Question(9609, "La capitale de l'Oman est...", listOf("Sohar", "Salalah", "Mascate", "Ibri"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Mascate est la capitale et la plus grande ville d'Oman, située sur la côte du golfe d'Oman. Elle abrite le siège du gouvernement et les principales institutions du pays."),
        Question(9610, "Quel est le plus haut sommet d'Afrique du Nord?", listOf("Pic Toubkal", "Pic Gueliz", "Mont Atlas", "Pic Tissoued"), 0, "Géographie", Difficulty.HARD, explanation = "Le Pic Toubkal culmine à 4 167 mètres dans le massif du Haut Atlas marocain, ce qui en fait le point culminant de l'Afrique du Nord."),
        Question(9611, "La capitale du Yémen est...", listOf("Aden", "Taiz", "Sanaa", "Hodeidah"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Sanaa est la capitale du Yémen depuis l'unification du pays en 1990, et l'une des plus anciennes villes habitées en continu au monde."),
        Question(9612, "Quel est le plus grand détroit du monde?", listOf("Détroit de Malacca", "Détroit de Béring", "Détroit de Magellan", "Détroit de Drake"), 3, "Géographie", Difficulty.HARD, explanation = "Le détroit de Drake, entre le cap Horn et l'Antarctique, est le plus large du monde avec environ 800 km, reliant les océans Atlantique et Pacifique."),
        Question(9613, "La capitale du Maroc est...", listOf("Casablanca", "Tanger", "Rabat", "Fès"), 2, "Géographie", Difficulty.EASY, explanation = "Rabat est la capitale administrative et politique du Maroc depuis 1912, sous le protectorat français, en remplacement de Fès."),
        Question(9614, "Quel montagnes forment la frontière entre le Maroc et l'Algérie?", listOf("Atlas du Haut", "Moyen Atlas", "Anti-Atlas", "Chaîne de l'Atlas"), 3, "Géographie", Difficulty.HARD, explanation = "La chaîne de l'Atlas, et plus précisément le massif de l'Atlas saharien, constitue une barrière naturelle majeure séparant le Maroc et l'Algérie sur leur frontière commune."),
        Question(9615, "La capitale de l'Algérie est...", listOf("Oran", "Constantine", "Alger", "Annaba"), 2, "Géographie", Difficulty.EASY, explanation = "Alger est la capitale de l'Algérie depuis l'indépendance en 1962, située sur la côte méditerranéenne."),
        Question(9616, "Quel est le plus long fleuve d'Afrique du Nord?", listOf("Draa", "Sous", "Nil", "Sebou"), 2, "Géographie", Difficulty.HARD, explanation = "Le Nil traverse l'Afrique du Nord-Est sur environ 6 650 km, ce qui en fait le plus long fleuve du continent africain."),
        Question(9617, "La capitale de la Tunisie est...", listOf("Sfax", "Sousse", "Tunis", "Gabès"), 2, "Géographie", Difficulty.EASY, explanation = "Tunis est la capitale de la Tunisie depuis l'indépendance en 1956, située sur la côte méditerranéenne. Elle abrite le siège du gouvernement et les principales institutions du pays."),
        Question(9618, "Quel est le point culminant de l'Afrique du Nord?", listOf("Pic Toubkal", "Mont Atlas", "Kef el-Ankhal", "Pic Tissoued"), 0, "Géographie", Difficulty.HARD, explanation = "Le Pic Toubkal, situé dans le Haut Atlas marocain, est le plus haut sommet d'Afrique du Nord avec 4 167 mètres d'altitude."),
        Question(9619, "La capitale de la Libye est...", listOf("Benghazi", "Misrata", "Tripoli", "Tobrouk"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Tripoli est la plus grande ville de Libye et son principal port sur la mer Méditerranée, servant de centre politique et économique du pays depuis l'indépendance."),
        Question(9620, "Quel est le plus grand port d'Afrique?", listOf("Port de Durban", "Port d'Abidjan", "Port de Lagos", "Port d'Alexandrie"), 3, "Géographie", Difficulty.HARD, explanation = "Le port d'Alexandrie, situé en Égypte sur la mer Méditerranée, est le plus grand port d'Afrique en termes de volume de marchandises traitées."),
        Question(9621, "La capitale du Soudan est...", listOf("Port Soudan", "Kassala", "Khartoum", "Renk"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Khartoum est la capitale du Soudan depuis l'indépendance du pays en 1956, située au confluent du Nil Blanc et du Nil Bleu."),
        Question(9622, "Quel est le plus grand archipel d'Afrique?", listOf("Archipel des Mascareignes", "Îles Seychelles", "Îles Comores", "Archipel de Socotra"), 0, "Géographie", Difficulty.HARD, explanation = "L'archipel des Mascareignes, comprenant La Réunion, Maurice et Rodrigues, est le plus grand d'Afrique par sa superficie terrestre totale."),
        Question(9623, "La capitale de la Somalie est...", listOf("Hargeisa", "Mogadiscio", "Kismayo", "Baidoa"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Mogadiscio est la capitale et la plus grande ville de la Somalie, située sur la côte de l'océan Indien. Elle est le principal centre politique, économique et culturel du pays."),
        Question(9624, "Quel est le plus grand pays d'Afrique orientale?", listOf("Kenya", "Ouganda", "Tanzanie", "Éthiopie"), 3, "Géographie", Difficulty.HARD, explanation = "L'Éthiopie est le plus grand pays d'Afrique orientale avec une superficie d'environ 1,1 million de kilomètres carrés, dépassant la Tanzanie et la Somalie."),
        Question(9625, "La capitale de l'Éthiopie est...", listOf("Dire Daoua", "Adis-Abeba", "Mekele", "Assela"), 1, "Géographie", Difficulty.EASY, explanation = "Addis-Abeba est la capitale de l'Éthiopie depuis 1889, fondée par l'empereur Ménélik II, et elle abrite le siège de l'Union africaine."),
        Question(9626, "Quel fleuve traverse l'Éthiopie?", listOf("Sénégal", "Nil", "Congo", "Zambèze"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Nil Bleu, principal affluent du Nil, prend sa source dans le lac Tana en Éthiopie."),
        Question(9627, "La capitale de Djibouti est...", listOf("Ali Sabieh", "Djibouti City", "Tadjourah", "Arta"), 1, "Géographie", Difficulty.HARD, explanation = "Djibouti City est à la fois la capitale et la plus grande ville du pays, portant le même nom que l'État."),
        Question(9628, "Quel est le plus grand désert de l'Afrique orientale?", listOf("Désert de Chalbi", "Désert du Danakil", "Désert de Janjero", "Désert de Ogaden"), 1, "Géographie", Difficulty.HARD, explanation = "Le désert du Danakil, situé dans la corne de l'Afrique (Éthiopie, Érythrée, Djibouti), est le plus grand désert d'Afrique orientale, connu pour ses températures extrêmes et ses paysages volcaniques."),
        Question(9629, "La capitale du Kenya est...", listOf("Mombasa", "Nairobi", "Kisumu", "Nakuru"), 1, "Géographie", Difficulty.EASY, explanation = "Nairobi est la plus grande ville du Kenya et son centre économique et politique. Elle a été fondée en 1899 comme dépôt ferroviaire et est devenue la capitale en 1907."),
        Question(9630, "Quel montagnes abritent le Kilimandjarou?", listOf("Chaîne des Usambara", "Monts Uluguru", "Chaîne des Pare", "Aucune (sommet isolé)"), 3, "Géographie", Difficulty.HARD, explanation = "Le Kilimandjaro est un volcan endormi et un sommet isolé, non rattaché à une chaîne de montagnes, ce qui en fait le plus haut sommet d'Afrique avec ses 5 895 mètres."),
        Question(9631, "La capitale de la Tanzanie est...", listOf("Dar es-Salaam", "Dodoma", "Arusha", "Mbeya"), 1, "Géographie", Difficulty.EASY, explanation = "Dodoma est devenue la capitale officielle de la Tanzanie en 1996, remplaçant Dar es Salam, principalement pour des raisons de centralisation géographique."),
        Question(9632, "Quel est le plus grand lac de la vallée du Rift?", listOf("Lac Turkana", "Lac Kyoga", "Lac Victoria", "Lac Tanganyika"), 3, "Géographie", Difficulty.HARD, explanation = "Le lac Tanganyika est le plus grand lac de la vallée du Rift en termes de volume et de profondeur, et le deuxième plus profond du monde. Il s'étend sur quatre pays d'Afrique de l'Est."),
        Question(9633, "La capitale de l'Ouganda est...", listOf("Jinja", "Kampala", "Gulu", "Mbale"), 1, "Géographie", Difficulty.EASY, explanation = "Kampala est la capitale et la plus grande ville de l'Ouganda, située sur les rives du lac Victoria. Elle est le centre politique, économique et culturel du pays."),
        Question(9634, "Quel fleuve traverse l'Ouganda?", listOf("Kagera", "Katonga", "Nil Blanc", "Sénégal"), 2, "Géographie", Difficulty.HARD, explanation = "Le Nil Blanc prend sa source dans le lac Victoria, dont la rive nord borde l'Ouganda, et traverse ce pays avant de poursuivre vers le Soudan."),
        Question(9635, "La capitale du Rwanda est...", listOf("Butare", "Muhanga", "Kigali", "Gisenyi"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Kigali est la capitale et la plus grande ville du Rwanda, située au centre du pays. Elle est le principal centre politique, économique et culturel du Rwanda."),
        Question(9636, "Quel est le plus grand lac de l'Afrique centrale?", listOf("Lac Bangweolo", "Lac Mobutu", "Lac Maï-Ndombe", "Lac Kivu"), 1, "Géographie", Difficulty.HARD, explanation = "Le lac Mobutu, aussi connu sous le nom de lac Albert, est le plus grand lac d'Afrique centrale, situé à la frontière entre l'Ouganda et la République démocratique du Congo."),
        Question(9637, "La capitale du Burundi est...", listOf("Bujumbura", "Gitega", "Ngozi", "Kayanza"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Gitega est devenue la capitale politique du Burundi en 2019, remplaçant Bujumbura qui reste la capitale économique."),
        Question(9638, "Quel est le plus long fleuve d'Afrique centrale?", listOf("Chari", "Oubangui", "Congo", "Kasai"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Congo est le plus long fleuve d'Afrique centrale, avec environ 4 700 km, traversant la République démocratique du Congo. Il est le deuxième plus long d'Afrique après le Nil."),
        Question(9639, "La capitale de la République Démocratique du Congo est...", listOf("Lubumbashi", "Kananga", "Kinshasa", "Kisangani"), 2, "Géographie", Difficulty.EASY, explanation = "Kinshasa est la capitale et la plus grande ville de la République Démocratique du Congo, située sur le fleuve Congo."),
        Question(9640, "Quel est le plus grand bassin fluvial du monde?", listOf("Bassin du Gange", "Bassin du Congo", "Bassin de l'Amazone", "Bassin du Mississippi"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le bassin de l'Amazone couvre environ 7 millions de km², traversant neuf pays d'Amérique du Sud, ce qui en fait le plus vaste réseau hydrographique de la planète."),
        Question(9641, "La capitale de la République du Congo est...", listOf("Dolisie", "Brazzaville", "Pointe-Noire", "Loubomo"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Brazzaville est la capitale de la République du Congo, située sur la rive nord du fleuve Congo, en face de Kinshasa, la capitale de la République démocratique du Congo."),
        Question(9642, "Quel est le plus grand désert d'Afrique centrale?", listOf("Désert de Kgalagadi", "Désert du Kalahari", "Désert du Namib", "Désert de Sinai"), 1, "Géographie", Difficulty.HARD, explanation = "Le Kalahari s'étend sur plusieurs pays d'Afrique australe, dont le Botswana et la Namibie, et est considéré comme le plus grand désert d'Afrique centrale."),
        Question(9643, "La capitale de l'Angola est...", listOf("Luanda", "Benguela", "Huambo", "Lobito"), 0, "Géographie", Difficulty.EASY, explanation = "Luanda est la capitale et la plus grande ville d'Angola, située sur la côte atlantique. Elle fut fondée par les Portugais en 1575."),
        Question(9644, "Quel fleuve est la frontière entre l'Angola et la Zambie?", listOf("Cassai", "Kwanza", "Zambèze", "Okavango"), 2, "Géographie", Difficulty.HARD, explanation = "Le Zambèze marque une partie de la frontière entre l'Angola et la Zambie, notamment dans sa section supérieure avant de traverser la Namibie et le Botswana."),
        Question(9645, "La capitale de la Zambie est...", listOf("Kitwe", "Ndola", "Lusaka", "Livingstone"), 2, "Géographie", Difficulty.EASY, explanation = "Lusaka est la capitale et la plus grande ville de la Zambie, située dans le centre-sud du pays. Elle a remplacé Livingstone comme capitale en 1935."),
        Question(9646, "Quel est le plus grand fleuve d'Afrique australe?", listOf("Okavango", "Kei", "Zambèze", "Limpopo"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Zambèze est le plus long fleuve d'Afrique australe, s'écoulant sur environ 2 574 km à travers six pays avant de se jeter dans l'océan Indien."),
        Question(9647, "La capitale du Zimbabwe est...", listOf("Bulawayo", "Harare", "Gweru", "Kwekwe"), 1, "Géographie", Difficulty.EASY, explanation = "Harare est la capitale et la plus grande ville du Zimbabwe, située dans le nord-est du pays. Elle a succédé à Salisbury en 1982 après l'indépendance."),
        Question(9648, "Quel montagnes séparent le Zimbabwe et la Zambie?", listOf("Chaîne des Muchinga", "Monts Zambezi", "Chaîne Victoria", "Montagnes de Inyanga"), 0, "Géographie", Difficulty.HARD, explanation = "La chaîne des Muchinga longe la vallée du Zambèze et forme une barrière naturelle entre la Zambie et le Zimbabwe."),
        Question(9649, "La capitale de la Namibie est...", listOf("Walvis Bay", "Windhoek", "Swakopmund", "Oshakati"), 1, "Géographie", Difficulty.EASY, explanation = "Windhoek est la capitale de la Namibie depuis l'indépendance du pays en 1990, située dans le centre du territoire."),
        Question(9650, "Quel désert borde la Namibie?", listOf("Désert de Kalahari", "Désert du Namib", "Désert de la Kalahari", "Désert de l'Atacama"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le désert du Namib s'étend le long de la côte atlantique de la Namibie, donnant son nom au pays."),
        Question(9651, "La capitale du Botswana est...", listOf("Francistown", "Gaborone", "Selibe-Phikwe", "Molepolole"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Gaborone est la capitale du Botswana depuis 1965, remplaçant Mafeking qui se trouvait en Afrique du Sud. La ville a été choisie pour sa position centrale et sa proximité avec le chemin de fer."),
        Question(9652, "Quel est le plus grand delta d'Afrique?", listOf("Delta de la Volta", "Delta du Niger", "Delta de l'Okavango", "Delta du Nil"), 2, "Géographie", Difficulty.HARD, explanation = "Le delta de l'Okavango, au Botswana, est le plus grand delta intérieur d'Afrique, formé par le fleuve Okavango qui se déverse dans le désert du Kalahari."),
        Question(9653, "La capitale de l'Afrique du Sud est...", listOf("Le Cap", "Johannesburg", "Pretoria", "Durban"), 2, "Géographie", Difficulty.EASY, explanation = "L'Afrique du Sud est l'un des rares pays à avoir trois capitales : Pretoria (administrative), Le Cap (législative) et Bloemfontein (judiciaire). Pretoria abrite le siège du gouvernement."),
        Question(9654, "Quel est le plus haut sommet d'Afrique du Sud?", listOf("Pic d'Injasuthi", "Cathédrale du Drakensbergh", "Mont aux Sources", "Thabana Ntlenyana"), 1, "Géographie", Difficulty.HARD, explanation = "Le plus haut sommet d'Afrique du Sud est la Cathédrale du Drakensbergh, culminant à 3 450 mètres dans la chaîne du Drakensberg."),
        Question(9655, "La capitale de la Lesotho est...", listOf("Teyateyaneng", "Maseru", "Leribe", "Mafeteng"), 1, "Géographie", Difficulty.HARD, explanation = "Maseru est la capitale et la plus grande ville du Lesotho, un pays enclavé dans l'est de l'Afrique du Sud."),
        Question(9656, "Quel est le plus grand désert d'Afrique australe?", listOf("Désert du Namib", "Désert de Kgalagadi", "Désert du Kalahari", "Désert de la Kalahari"), 2, "Géographie", Difficulty.HARD, explanation = "Le Kalahari s'étend sur plusieurs pays d'Afrique australe, dont le Botswana, la Namibie et l'Afrique du Sud, et couvre environ 900 000 km², ce qui en fait le plus grand désert de cette région."),
        Question(9657, "La capitale de l'Eswatini est...", listOf("Manzini", "Mbabane", "Siteki", "Nhlangano"), 1, "Géographie", Difficulty.HARD, explanation = "Mbabane est la capitale administrative et la plus grande ville d'Eswatini, un petit royaume d'Afrique australe."),
        Question(9658, "Quel fleuve traverse l'Afrique du Sud?", listOf("Limpopo", "Vaal", "Orange", "Tous les trois"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Les trois principaux fleuves d'Afrique du Sud sont l'Orange, le Limpopo et le Vaal, qui traversent tous le pays."),
        Question(9659, "La capitale du Mozambique est...", listOf("Beira", "Maputo", "Quelimane", "Inhambane"), 1, "Géographie", Difficulty.EASY, explanation = "Maputo, anciennement Lourenço Marques, est la capitale du Mozambique depuis l'indépendance du pays en 1975. Elle est située sur la côte sud-est de l'Afrique, au bord de l'océan Indien."),
        Question(9660, "Quel est le plus grand port d'Afrique australe?", listOf("Port de Maputo", "Port de Beira", "Port de Richards Bay", "Port de Durban"), 3, "Géographie", Difficulty.HARD, explanation = "Le port de Durban, en Afrique du Sud, est le plus grand et le plus actif d'Afrique australe, traitant la majorité du trafic maritime de la région."),
        Question(9661, "La capitale de Madagascar est...", listOf("Antsirabe", "Toliara", "Antananarivo", "Mahajanga"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Antananarivo est la capitale de Madagascar depuis l'époque du royaume merina au XVIIIe siècle. Son nom signifie « la ville des mille guerriers » en malgache."),
        Question(9662, "Quel océan entoure Madagascar?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Golfe du Bengale"), 1, "Géographie", Difficulty.EASY, explanation = "Madagascar est une île située dans l'océan Indien, au large de la côte sud-est de l'Afrique."),
        Question(9663, "La capitale des Seychelles est...", listOf("Mahe", "Victoria", "Praslin", "La Digue"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Victoria est la capitale des Seychelles, située sur l'île de Mahé. C'est la seule ville du pays et elle abrite la majorité de sa population."),
        Question(9664, "Quel est le plus grand port d'Afrique de l'Ouest?", listOf("Port de Casablanca", "Port de Lagos", "Port de Dakar", "Port d'Abidjan"), 1, "Géographie", Difficulty.HARD, explanation = "Le port de Lagos, au Nigeria, est le plus grand et le plus actif d'Afrique de l'Ouest, traitant une part majeure du commerce maritime régional."),
        Question(9665, "La capitale du Mauritanie est...", listOf("Atar", "Tidjikja", "Nouakchott", "Kaédi"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Nouakchott est la capitale de la Mauritanie depuis 1958, choisie pour sa position centrale sur la côte atlantique."),
        Question(9666, "Quel est le plus grand désert de l'Afrique de l'Ouest?", listOf("Désert du Ténéré", "Sahara", "Désert du Namib", "Désert du Kalahari"), 1, "Géographie", Difficulty.HARD, explanation = "Le Sahara s'étend sur plusieurs pays d'Afrique du Nord et de l'Ouest, comme le Mali, le Niger et la Mauritanie, ce qui en fait le plus vaste désert chaud de la région."),
        Question(9667, "La capitale du Sénégal est...", listOf("Saint-Louis", "Kaolack", "Dakar", "Tambacounda"), 2, "Géographie", Difficulty.EASY, explanation = "Dakar est la capitale du Sénégal depuis l'indépendance en 1960. Située sur la presqu'île du Cap-Vert, c'est la ville la plus peuplée du pays."),
        Question(9668, "Quel fleuve traverse le Sénégal?", listOf("Niger", "Sénégal", "Gambie", "Volta"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Sénégal prend sa source en Guinée et sert de frontière entre le Sénégal et la Mauritanie avant de se jeter dans l'océan Atlantique."),
        Question(9669, "La capitale de la Gambie est...", listOf("Serekunda", "Banjul", "Bakau", "Farafenni"), 1, "Géographie", Difficulty.HARD, explanation = "Banjul est située sur l'île de Sainte-Marie, à l'embouchure du fleuve Gambie, et a été choisie comme capitale en 1965 lors de l'indépendance du pays."),
        Question(9670, "Quel est le plus petit pays d'Afrique?", listOf("Malawi", "Seychelles", "Djibouti", "Mauritanie"), 1, "Géographie", Difficulty.HARD, explanation = "Les Seychelles sont un archipel de l'océan Indien, avec une superficie totale d'environ 455 km², ce qui en fait le plus petit pays d'Afrique en termes de surface terrestre."),
        Question(9671, "La capitale de la Guinée-Bissau est...", listOf("Gabu", "Bolama", "Bissau", "Cacheu"), 2, "Géographie", Difficulty.HARD, explanation = "Bissau est à la fois la capitale et la plus grande ville de la Guinée-Bissau, située sur l'estuaire du fleuve Geba."),
        Question(9672, "Quel fleuve traverse la Guinée-Bissau?", listOf("Corubal", "Cacheu", "Geba", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le fleuve Geba, le fleuve Cacheu et le fleuve Corubal traversent tous la Guinée-Bissau."),
        Question(9673, "La capitale de la Guinée est...", listOf("Kindia", "Mamou", "Conakry", "Forécariah"), 2, "Géographie", Difficulty.EASY, explanation = "Conakry est la capitale et la plus grande ville de la Guinée, située sur la côte atlantique."),
        Question(9674, "Quel montagnes forment la frontière entre la Guinée et la Côte d'Ivoire?", listOf("Chaîne des Nimba", "Monts du Fouta-Djallon", "Chaîne du Simandou", "Montagnes du Gaoual"), 0, "Géographie", Difficulty.HARD, explanation = "La chaîne des Nimba, située à cheval entre la Guinée, la Côte d'Ivoire et le Liberia, constitue la frontière naturelle entre la Guinée et la Côte d'Ivoire."),
        Question(9675, "La capitale de la Sierra Leone est...", listOf("Bo", "Kenema", "Freetown", "Makeni"), 2, "Géographie", Difficulty.EASY, explanation = "Freetown a été fondée en 1787 comme refuge pour les esclaves affranchis, d'où son nom. Elle est le principal port et centre politique du pays."),
        Question(9676, "Quel est le plus grand fleuve d'Afrique de l'Ouest?", listOf("Volta", "Sénégal", "Niger", "Gambie"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Niger est le plus long fleuve d'Afrique de l'Ouest, avec environ 4 180 km, traversant plusieurs pays comme le Mali, le Niger et le Nigeria avant de se jeter dans le golfe de Guinée."),
        Question(9677, "La capitale du Liberia est...", listOf("Monrovia", "Buchanan", "Harper", "Gbarnga"), 0, "Géographie", Difficulty.EASY, explanation = "Monrovia a été nommée en l'honneur de James Monroe, le cinquième président des États-Unis, en raison du rôle de l'American Colonization Society dans la colonisation du Liberia."),
        Question(9678, "Quel mont abritent la plus grande forêt d'Afrique?", listOf("Mont Cameroun", "Mont Kilimandjarou", "Aucune réponse", "Mont Kenia"), 2, "Géographie", Difficulty.HARD, explanation = "Aucun mont africain n'abrite la plus grande forêt du continent. La plus grande forêt d'Afrique est le bassin du Congo, une vaste région de plaine."),
        Question(9679, "La capitale de la Côte d'Ivoire est...", listOf("Abidjan", "Bouaké", "Yamoussoukro", "Gagnoa"), 2, "Géographie", Difficulty.EASY, explanation = "Yamoussoukro est la capitale politique et administrative de la Côte d'Ivoire depuis 1983, remplaçant Abidjan qui reste la capitale économique."),
        Question(9680, "Quel fleuve traverse la Côte d'Ivoire?", listOf("Comoé", "Bandama", "Sassandra", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Les fleuves Comoé, Bandama et Sassandra traversent tous la Côte d'Ivoire du nord au sud pour se jeter dans l'océan Atlantique."),
        Question(9681, "La capitale du Ghana est...", listOf("Kumasi", "Accra", "Sekondi", "Tamale"), 1, "Géographie", Difficulty.EASY, explanation = "Accra est la capitale et la plus grande ville du Ghana, située sur la côte atlantique du pays."),
        Question(9682, "Quel fleuve traverse le Ghana?", listOf("Ankobra", "Volta", "Pra", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le Ghana est traversé par trois fleuves principaux : la Volta Noire, la Volta Blanche et la Volta Rouge, qui se rejoignent pour former le fleuve Volta."),
        Question(9683, "La capitale du Togo est...", listOf("Lomé", "Kara", "Sokodé", "Atakpamé"), 0, "Géographie", Difficulty.EASY, explanation = "Lomé est la capitale et la plus grande ville du Togo, située sur la côte du Golfe de Guinée. Elle est le principal port et centre économique du pays."),
        Question(9684, "Quel fleuve traverse le Togo?", listOf("Mono", "Ankobra", "Volta", "Pra"), 0, "Géographie", Difficulty.HARD, explanation = "Le Mono prend sa source au Bénin et traverse le Togo sur environ 400 kilomètres avant de se jeter dans l'océan Atlantique, formant la frontière entre les deux pays."),
        Question(9685, "La capitale du Bénin est...", listOf("Cotonou", "Abomey", "Porto-Novo", "Parakou"), 2, "Géographie", Difficulty.EASY, explanation = "Porto-Novo est la capitale officielle du Bénin, tandis que Cotonou est la capitale économique et le siège du gouvernement."),
        Question(9686, "Quel fleuve traverse le Bénin?", listOf("Volta", "Niger", "Comoé", "Sénégal"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Niger traverse le Bénin sur sa partie nord, formant une frontière naturelle avec le Niger."),
        Question(9687, "La capitale du Nigéria est...", listOf("Lagos", "Ibadan", "Abuja", "Kano"), 2, "Géographie", Difficulty.EASY, explanation = "Abuja a remplacé Lagos comme capitale du Nigéria en 1991, choisie pour sa position centrale et moins peuplée."),
        Question(9688, "Quel est le plus grand pays du continent africain par population?", listOf("Égypte", "Éthiopie", "Nigeria", "Congo"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Nigeria dépasse les 220 millions d'habitants, ce qui en fait le pays le plus peuplé d'Afrique, loin devant l'Éthiopie et la République démocratique du Congo."),
        Question(9689, "La capitale du Cameroun est...", listOf("Douala", "Yaoundé", "Buea", "Bafoussam"), 1, "Géographie", Difficulty.EASY, explanation = "Yaoundé est la capitale politique et administrative du Cameroun depuis 1909, sous administration allemande, puis confirmée après l'indépendance en 1960."),
        Question(9690, "Quel montagnes abritent le plus haut sommet d'Afrique centrale?", listOf("Chaîne des Adamaoua", "Chaîne du Cameroun", "Monts de l' Adamaoua", "Chaîne des Mayombe"), 2, "Géographie", Difficulty.HARD, explanation = "Les monts de l'Adamaoua, situés au Cameroun, culminent à environ 2 650 mètres, ce qui en fait le plus haut massif d'Afrique centrale."),
        Question(9691, "La capitale de la Guinée Équatoriale est...", listOf("Bata", "Malabo", "Ebebiyin", "Mongomo"), 1, "Géographie", Difficulty.HARD, explanation = "Malabo, située sur l'île de Bioko, est la capitale de la Guinée Équatoriale depuis son indépendance de l'Espagne en 1968."),
        Question(9692, "Quel est le plus grand archipel de l'Afrique de l'Ouest?", listOf("Îles Bijagos", "Îles du Cap-Vert", "Île de Bioko", "Îles Comores"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel du Cap-Vert, situé dans l'océan Atlantique, est le plus grand d'Afrique de l'Ouest avec dix îles principales et plusieurs îlots."),
        Question(9693, "La capitale de São Tomé et Príncipe est...", listOf("Santo António", "São Tomé", "Neves", "Ava"), 1, "Géographie", Difficulty.HARD, explanation = "São Tomé est la plus grande ville du pays et abrite les institutions gouvernementales, ce qui en fait la capitale de l'archipel."),
        Question(9694, "Quel océan entoure le Cap-Vert?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Golfe du Bengale"), 0, "Géographie", Difficulty.HARD, explanation = "Le Cap-Vert est un archipel situé dans l'océan Atlantique, au large des côtes de l'Afrique de l'Ouest."),
        Question(9695, "La capitale du Gabon est...", listOf("Port-Gentil", "Libreville", "Oyem", "Franciville"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Libreville a été fondée en 1849 par des esclaves libérés, d'où son nom. Elle est devenue la capitale du Gabon à l'indépendance en 1960."),
        Question(9696, "Quel fleuve traverse le Gabon?", listOf("Ngounié", "Ogooué", "Ivindo", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le Gabon est traversé par trois grands fleuves : l'Ogooué, le Komo et le Nyanga, qui drainent tous le territoire."),
        Question(9697, "La capitale de la Guinée Équatoriale (Malabo) est...", listOf("Sur la côte", "Sur une île", "En montagne", "En désert"), 1, "Géographie", Difficulty.HARD, explanation = "Malabo est située sur l'île de Bioko, au large des côtes camerounaises, ce qui en fait une capitale insulaire."),
        Question(9698, "Quel est le plus grand fleuve d'Afrique centrale?", listOf("Kassaï", "Oubangui", "Congo", "Lualaba"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Congo, long de 4 700 km, est le plus grand d'Afrique centrale par son débit et son bassin versant. Il traverse la République démocratique du Congo et constitue une voie navigable majeure."),
        Question(9699, "La capitale du Tchad est...", listOf("Abéché", "Moundou", "Sarh", "N'Djaména"), 3, "Géographie", Difficulty.MEDIUM, explanation = "N'Djaména est la capitale du Tchad depuis 1960, année de l'indépendance du pays. Anciennement appelée Fort-Lamy, elle est située au confluent des fleuves Chari et Logone."),
        Question(9700, "Quel est le plus grand lac d'Afrique centrale?", listOf("Lac Kivu", "Lac Tanganyika", "Lac Mobutu", "Lac Léopold II"), 2, "Géographie", Difficulty.HARD, explanation = "Le lac Mobutu, aussi connu sous le nom de lac Albert, est le plus grand lac d'Afrique centrale par sa superficie, situé à la frontière entre l'Ouganda et la République démocratique du Congo."),
        Question(9701, "La capitale de la Centrafrique est...", listOf("Bambari", "Bouar", "Bangui", "Birao"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Bangui est la capitale de la République centrafricaine, située sur les rives du fleuve Oubangui, qui marque la frontière avec la République démocratique du Congo."),
        Question(9702, "Quel fleuve traverse la Centrafrique?", listOf("Logone", "Oubangui", "Shari", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le territoire centrafricain est drainé par trois grands fleuves : l'Oubangui, le Chari et le Sangha, qui forment respectivement les frontières sud, nord-ouest et sud-ouest du pays."),
        Question(9703, "La capitale du Cameroun (Yaoundé) est...", listOf("Sur le plan", "En montagne", "Sur la côte", "En forêt"), 1, "Géographie", Difficulty.HARD, explanation = "Yaoundé est située sur un plateau à environ 750 mètres d'altitude, dans une région de collines et de reliefs accidentés."),
        Question(9704, "Quel est le plus grand fleuve d'Afrique de l'Ouest?", listOf("Volta", "Sénégal", "Niger", "Gambie"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Niger, long d'environ 4 180 km, traverse plusieurs pays d'Afrique de l'Ouest comme le Mali, le Niger et le Nigeria, ce qui en fait le plus grand fleuve de la région."),
        Question(9705, "La capitale du Mali est...", listOf("Gao", "Tombouctou", "Bamako", "Ségou"), 2, "Géographie", Difficulty.EASY, explanation = "Bamako est la capitale du Mali depuis l'indépendance du pays en 1960, située sur les rives du fleuve Niger."),
        Question(9706, "Quel fleuve traverse le Mali?", listOf("Sénégal", "Volta", "Niger", "Tous les trois"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Niger traverse le Mali sur environ 1 700 kilomètres, servant de voie de transport et d'irrigation essentielle pour le pays."),
        Question(9707, "La capitale du Burkina Faso est...", listOf("Bobo-Dioulasso", "Ouagadougou", "Koudougou", "Dédougou"), 1, "Géographie", Difficulty.EASY, explanation = "Ouagadougou est la capitale politique et administrative du Burkina Faso, située au centre du pays. Elle est également la plus grande ville du pays."),
        Question(9708, "Quel fleuve traverse le Burkina Faso?", listOf("Volta", "Niger", "Sénégal", "Gambie"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le Burkina Faso est traversé par le fleuve Volta, qui donne son nom à la région historique de Haute-Volta, ancien nom du pays jusqu'en 1984."),
        Question(9709, "La capitale du Niger est...", listOf("Maradi", "Zinder", "Niamey", "Agadez"), 2, "Géographie", Difficulty.EASY, explanation = "Niamey est la capitale du Niger depuis l'indépendance du pays en 1960, située sur les rives du fleuve Niger dans le sud-ouest du territoire."),
        Question(9710, "Quel fleuve traverse le Niger?", listOf("Sénégal", "Niger", "Volta", "Gambie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Niger traverse le Niger, dont il tire son nom, et constitue une artère vitale pour le pays en fournissant eau et irrigation dans une région aride."),
        Question(9711, "Quel est le plus grand archipel du monde?", listOf("Hawaï", "Maldives", "Indonésie", "Philippines"), 2, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel du monde avec plus de 17 000 îles, s'étendant entre l'océan Indien et l'océan Pacifique."),
        Question(9712, "Quel est le plus petit pays d'Asie?", listOf("Bhoutan", "Brunei", "Bahreïn", "Singapour"), 3, "Géographie", Difficulty.HARD, explanation = "Singapour est une cité-État insulaire d'Asie du Sud-Est avec une superficie d'environ 728 km², ce qui en fait le plus petit pays du continent asiatique."),
        Question(9713, "Quel continent a le plus de lacs?", listOf("Asie", "Amérique du Nord", "Europe", "Afrique"), 2, "Géographie", Difficulty.HARD, explanation = "L'Europe compte plus de 1,5 million de lacs, principalement en Finlande, en Suède et en Russie, ce qui en fait le continent le plus riche en lacs."),
        Question(9714, "Quel est le plus grand estuaire du monde?", listOf("Estuaire du Gange", "Estuaire de l'Amazone", "Estuaire de l'Orénoque", "Estuaire du Mississippi"), 0, "Géographie", Difficulty.HARD, explanation = "L'estuaire du Gange, situé au Bangladesh et en Inde, est le plus grand du monde en superficie et en débit d'eau, formant le delta du Gange-Brahmapoutre."),
        Question(9715, "Quel est le plus grand fleuve d'Amérique du Nord?", listOf("Yukon", "Mississippi", "Mackenzie", "Rio Bravo"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Mississippi s'étend sur environ 3 730 kilomètres, drainant une grande partie du continent nord-américain avec son affluent le Missouri."),
        Question(9716, "La capitale du Groenland est...", listOf("Sisimiut", "Nuuk", "Aasiaat", "Qeqertarsuaq"), 1, "Géographie", Difficulty.HARD, explanation = "Nuuk est la capitale et la plus grande ville du Groenland, située sur la côte sud-ouest de l'île. Elle abrite le siège du gouvernement groenlandais."),
        Question(9717, "Quel est le plus grand glacier d'Amérique du Nord?", listOf("Glacier du Peito", "Glaciers d'Alaska", "Glacier du Rhône", "Glacier du Mendenhall"), 1, "Géographie", Difficulty.HARD, explanation = "Le glacier d'Alaska, situé dans la chaîne côtière du Pacifique, est le plus vaste d'Amérique du Nord par sa superficie et son volume de glace."),
        Question(9718, "La capitale d'Haïti est...", listOf("Cap-Haïtien", "Port-au-Prince", "Les Cayes", "Jérémie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Port-au-Prince est la capitale et la plus grande ville d'Haïti, située sur le golfe de la Gonâve. Elle fut fondée en 1749 par les colons français."),
        Question(9719, "Quel est le plus grand archipel des Caraïbes?", listOf("Îles Bahamas", "Îles Turques et Caïques", "Îles Vierges", "Îles Caïmans"), 0, "Géographie", Difficulty.HARD, explanation = "Les Bahamas comptent plus de 700 îles et cayes, ce qui en fait le plus vaste archipel des Caraïbes en termes de superficie et de nombre d'îles."),
        Question(9720, "La capitale de la Jamaïque est...", listOf("Montego Bay", "Kingston", "Spanish Town", "Portmore"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Kingston est la capitale et la plus grande ville de la Jamaïque, située sur la côte sud-est de l'île."),
        Question(9721, "Quel est le plus grand port des Caraïbes?", listOf("Port de Montego Bay", "Port de Kingston", "Port de Trinidad", "Port de La Havane"), 0, "Géographie", Difficulty.HARD, explanation = "Le port de Montego Bay, en Jamaïque, est le plus grand port des Caraïbes en termes de trafic de conteneurs et de croisières, jouant un rôle clé dans l'économie régionale."),
        Question(9722, "La capitale de la République Dominicaine est...", listOf("Santiago", "La Romana", "Saint-Domingue", "Punta Cana"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Saint-Domingue, fondée en 1496 par Barthélemy Colomb, est la plus ancienne ville européenne des Amériques et le siège du gouvernement dominicain."),
        Question(9723, "Quel océan entoure les Caraïbes?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Golfe du Mexique"), 0, "Géographie", Difficulty.EASY, explanation = "La mer des Caraïbes est une mer bordière de l'océan Atlantique, située à l'est de l'Amérique centrale et au nord de l'Amérique du Sud."),
        Question(9724, "La capitale de Cuba est...", listOf("Santiago", "Camagüey", "La Havane", "Guantánamo"), 2, "Géographie", Difficulty.EASY, explanation = "La Havane est la capitale et la plus grande ville de Cuba, située sur la côte nord-ouest de l'île. Elle est le principal centre politique, économique et culturel du pays."),
        Question(9725, "Quel est le plus long fleuve de la Caraïbe?", listOf("Fleuve Artibonite", "Fleuve Magdalena", "Fleuve Orénoque", "Fleuve Grijalva"), 2, "Géographie", Difficulty.HARD, explanation = "L'Orénoque, long d'environ 2 140 km, traverse le Venezuela et se jette dans l'océan Atlantique, ce qui en fait le plus long fleuve de la région caraïbe."),
        Question(9726, "La capitale de la Barbade est...", listOf("Bathsheba", "Bridgetown", "Belleplaine", "Bathurst"), 1, "Géographie", Difficulty.HARD, explanation = "Bridgetown est la capitale et la plus grande ville de la Barbade, située sur la côte sud-ouest de l'île."),
        Question(9727, "Quel île des Caraïbes est la plus grande?", listOf("Cuba", "Hispaniola", "Jamaïque", "Porto Rico"), 0, "Géographie", Difficulty.HARD, explanation = "Cuba est la plus grande île des Caraïbes avec une superficie d'environ 109 884 km², dépassant largement Hispaniola et la Jamaïque."),
        Question(9728, "La capitale de Sainte-Lucie est...", listOf("Gros-Islet", "Castries", "Soufrière", "Laborie"), 1, "Géographie", Difficulty.HARD, explanation = "Castries est la capitale de Sainte-Lucie, une île des Caraïbes, et sert de centre administratif et économique du pays depuis l'époque coloniale britannique."),
        Question(9729, "Quel est le plus haut sommet des Caraïbes?", listOf("Pic la Selle", "Pic Duarte", "Pic Morne-la-Selle", "Pic Christophe"), 1, "Géographie", Difficulty.HARD, explanation = "Le Pic Duarte, culminant à 3 098 mètres, est le point le plus élevé des Caraïbes et se situe en République dominicaine."),
        Question(9730, "La capitale de la Grenade est...", listOf("Grenville", "Saint-Georges", "Sauteurs", "Gouyave"), 1, "Géographie", Difficulty.HARD, explanation = "Saint-Georges est la capitale de la Grenade, un État insulaire des Caraïbes, en raison de son port naturel et de son rôle historique de centre administratif et économique."),
        Question(9731, "Quel est le plus grand pays de l'Amérique centrale?", listOf("Honduras", "Guatemala", "Nicaragua", "Panama"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Guatemala est le pays le plus peuplé d'Amérique centrale et possède la plus grande superficie de la région, devant le Honduras et le Nicaragua."),
        Question(9732, "La capitale du Honduras est...", listOf("San Pedro Sula", "Tegucigalpa", "La Ceiba", "Choluteca"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Tegucigalpa est la capitale du Honduras depuis 1880, remplaçant Comayagua. Elle est aussi la plus grande ville du pays."),
        Question(9733, "Quel est le plus grand fleuve d'Amérique centrale?", listOf("Usumacinta", "Patuca", "Motagua", "Grijalva"), 0, "Géographie", Difficulty.HARD, explanation = "L'Usumacinta est le plus grand fleuve d'Amérique centrale, formant une frontière naturelle entre le Mexique et le Guatemala. Il mesure environ 1 000 kilomètres de long et traverse la forêt tropicale du Petén."),
        Question(9734, "La capitale du Guatemala est...", listOf("Antigua", "Chichicastenango", "Quetzaltenango", "Guatemala City"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Guatemala City est la capitale et la plus grande ville du Guatemala, située dans la région sud du pays. Elle est le centre politique, économique et culturel du pays."),
        Question(9735, "Quel montagnes abritent le plus haut sommet d'Amérique centrale?", listOf("Sierra Madre de Chiapas", "Cordillère centrale", "Sierra Madre Oriental", "Chaîne des Andes"), 0, "Géographie", Difficulty.HARD, explanation = "Le point culminant d'Amérique centrale, le volcan Tajumulco (4 220 m), se trouve dans la Sierra Madre de Chiapas, une chaîne de montagnes qui s'étend du Mexique au Guatemala."),
        Question(9736, "La capitale du Belize est...", listOf("Belize City", "Belmopan", "Orange Walk", "San Ignacio"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Belmopan est devenue la capitale du Belize en 1970 après la destruction de Belize City par l'ouragan Hattie en 1961."),
        Question(9737, "Quel est le plus grand récif corallien d'Amérique centrale?", listOf("Récif de Mesoamérica", "Récif de Belize", "Récif de Akumal", "Récif de Xcaret"), 0, "Géographie", Difficulty.HARD, explanation = "Le récif de Mesoamérica s'étend sur plus de 1 000 km le long des côtes du Belize, du Guatemala, du Honduras et du Mexique, ce qui en fait le plus grand récif corallien d'Amérique centrale."),
        Question(9738, "La capitale du Salvador est...", listOf("Santa Ana", "San Salvador", "La Libertad", "Sonsonate"), 1, "Géographie", Difficulty.EASY, explanation = "San Salvador est la capitale et la plus grande ville du Salvador, située dans le département de San Salvador. Elle est le centre politique, économique et culturel du pays."),
        Question(9739, "Quel fleuve est la frontière entre le Honduras et le Guatemala?", listOf("Patuca", "Motagua", "Usumacinta", "Grijalva"), 2, "Géographie", Difficulty.HARD, explanation = "Le fleuve Usumacinta marque une partie de la frontière entre le Guatemala et le Mexique, mais il ne sépare pas le Honduras du Guatemala. La frontière entre le Honduras et le Guatemala est principalement terrestre."),
        Question(9740, "La capitale du Nicaragua est...", listOf("León", "Managua", "Granada", "Estelí"), 1, "Géographie", Difficulty.EASY, explanation = "Managua est la capitale du Nicaragua depuis 1852, située sur la rive sud du lac Managua. Elle a remplacé León comme capitale après des rivalités historiques entre les villes."),
        Question(9741, "Quel est le plus grand lac d'Amérique centrale?", listOf("Lac Atitlán", "Lac Arenal", "Lac de Nicaragua", "Lac de Izabal"), 2, "Géographie", Difficulty.HARD, explanation = "Le lac de Nicaragua est le plus grand lac d'Amérique centrale avec une superficie d'environ 8 264 km². Il est également connu pour abriter des requins d'eau douce."),
        Question(9742, "La capitale du Costa Rica est...", listOf("Alajuela", "San José", "Cartago", "Heredia"), 1, "Géographie", Difficulty.EASY, explanation = "San José est la capitale du Costa Rica, située dans la vallée centrale du pays. Elle abrite la majorité des institutions gouvernementales et économiques du pays."),
        Question(9743, "Quel est le plus grand volcan d'Amérique centrale?", listOf("Volcán Arenal", "Volcán Irazú", "Volcán Ometepe", "Volcán Atitlán"), 0, "Géographie", Difficulty.HARD, explanation = "Le Volcán Arenal, au Costa Rica, est considéré comme le plus grand volcan d'Amérique centrale en raison de sa hauteur de 1 670 mètres et de son activité historique majeure."),
        Question(9744, "La capitale du Panama est...", listOf("Colón", "Panama City", "David", "Penonomé"), 1, "Géographie", Difficulty.EASY, explanation = "Panama City est la capitale et la plus grande ville du Panama, située à l'entrée du canal de Panama sur la côte Pacifique."),
        Question(9745, "Quel détroit relie l'Amérique du Nord et l'Amérique centrale?", listOf("Détroit de Béring", "Détroit de Yucatán", "Canal de Panamá", "Détroit de Panama"), 2, "Géographie", Difficulty.HARD, explanation = "Le canal de Panama, bien que souvent considéré comme un détroit artificiel, relie l'océan Atlantique au Pacifique et sépare l'Amérique du Nord de l'Amérique centrale."),
        Question(9746, "Quel fleuve traverse le Venezuela?", listOf("Caura", "Orénoque", "Caroni", "Apure"), 1, "Géographie", Difficulty.MEDIUM, explanation = "L'Orénoque est l'un des plus longs fleuves d'Amérique du Sud, traversant le Venezuela d'ouest en est avant de se jeter dans l'océan Atlantique."),
        Question(9747, "La capitale du Venezuela est...", listOf("Maracaibo", "Caracas", "Barquisimeto", "Valencia"), 1, "Géographie", Difficulty.EASY, explanation = "Caracas est la capitale du Venezuela depuis 1830, située dans une vallée côtière au nord du pays. Elle concentre les institutions politiques et économiques de la nation."),
        Question(9748, "Quel est le plus haut sommet du Venezuela?", listOf("Pic Espejo", "Pic Humboldt", "Pic Bonpland", "Pic de la Selle"), 1, "Géographie", Difficulty.HARD, explanation = "Le Pic Humboldt, culminant à 4 940 mètres, est le plus haut sommet du Venezuela, situé dans la Sierra Nevada de Mérida, une chaîne des Andes."),
        Question(9749, "La capitale de la Colombie est...", listOf("Medellín", "Cali", "Bogotá", "Barranquilla"), 2, "Géographie", Difficulty.EASY, explanation = "Bogotá est la capitale de la Colombie depuis 1886, située sur un haut plateau des Andes. C'est le centre politique, économique et culturel du pays."),
        Question(9750, "Quel fleuve traverse la Colombie?", listOf("Magdalena", "Atrato", "Cauca", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le fleuve Magdalena, le Cauca et l'Atrato sont les trois principaux fleuves qui traversent la Colombie, chacun jouant un rôle clé dans la géographie et l'économie du pays."),
        Question(9751, "Quel est le plus grand désert d'Amérique du Sud?", listOf("Désert de Atacama", "Désert de Sechura", "Désert de Patagonie", "Pampas"), 0, "Géographie", Difficulty.HARD, explanation = "Le désert d'Atacama, situé au nord du Chili, est le plus grand désert d'Amérique du Sud et l'un des plus arides au monde en raison de sa position entre la cordillère des Andes et l'océan Pacifique."),
        Question(9752, "La capitale de l'Équateur est...", listOf("Guayaquil", "Quito", "Cuenca", "Ambato"), 1, "Géographie", Difficulty.EASY, explanation = "Quito est la capitale de l'Équateur, située dans les Andes à une altitude de 2 850 mètres, ce qui en fait la deuxième plus haute capitale du monde."),
        Question(9753, "Quel montagnes abritent le plus haut sommet d'Amérique du Sud?", listOf("Chaîne côtière", "Cordillère occidentale", "Cordillère orientale", "Andes"), 3, "Géographie", Difficulty.MEDIUM, explanation = "La cordillère des Andes traverse toute l'Amérique du Sud et son sommet, l'Aconcagua, culmine à 6 961 mètres, ce qui en fait le plus haut du continent."),
        Question(9754, "La capitale du Pérou est...", listOf("Arequipa", "Cuzco", "Lima", "Trujillo"), 2, "Géographie", Difficulty.EASY, explanation = "Lima est la capitale du Pérou depuis sa fondation par les conquistadors espagnols en 1535. Elle est située sur la côte centrale du pays, au bord de l'océan Pacifique."),
        Question(9755, "Quel fleuve traverse le Pérou?", listOf("Urubamba", "Ucayali", "Amazone", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le Pérou est traversé par trois grands fleuves : l'Amazone, l'Ucayali et le Marañón, ces deux derniers étant les principales sources de l'Amazone."),
        Question(9756, "Quel est le plus grand fleuve du monde?", listOf("Nil", "Amazone", "Congo", "Mississippi"), 1, "Géographie", Difficulty.MEDIUM, explanation = "L'Amazone est le plus grand fleuve du monde en volume d'eau, avec un débit moyen d'environ 209 000 m³/s, dépassant largement les autres fleuves comme le Nil."),
        Question(9757, "La capitale du Brésil est...", listOf("Rio de Janeiro", "São Paulo", "Brasília", "Salvador"), 2, "Géographie", Difficulty.EASY, explanation = "Brasília est devenue la capitale du Brésil en 1960, construite spécialement pour remplacer Rio de Janeiro et déplacer le centre politique vers l'intérieur du pays."),
        Question(9758, "Quel fleuve traverse le Brésil?", listOf("Rio Madeira", "Rio Negro", "Amazone", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le Brésil est traversé par l'Amazone, le São Francisco et le Paraná, qui sont les trois principaux fleuves du pays."),
        Question(9759, "Quel est le plus grand désert du Brésil?", listOf("Désert de Atacama", "Désert de Iquique", "Sertão", "Cerrado"), 2, "Géographie", Difficulty.HARD, explanation = "Le Sertão est une vaste région semi-aride du nord-est du Brésil, souvent considérée comme le plus grand désert du pays en raison de son climat sec et de sa végétation clairsemée."),
        Question(9760, "La capitale de la Bolivie est...", listOf("Cochabamba", "Sucre", "La Paz", "Santa Cruz de la Sierra"), 2, "Géographie", Difficulty.EASY, explanation = "La Paz est la capitale administrative et le siège du gouvernement bolivien, tandis que Sucre est la capitale constitutionnelle et judiciaire."),
        Question(9761, "Quel est le plus grand lac d'Amérique du Sud?", listOf("Lac Titicaca", "Lac Poopó", "Lac Coipasa", "Lac Chinchorro"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le lac Titicaca, situé à la frontière entre le Pérou et la Bolivie, est le plus grand lac d'Amérique du Sud par sa superficie et son volume d'eau, culminant à 3 812 mètres d'altitude."),
        Question(9762, "La capitale de l'Uruguay est...", listOf("Colonia", "Salto", "Montevideo", "Punta del Este"), 2, "Géographie", Difficulty.EASY, explanation = "Montevideo est la capitale et la plus grande ville de l'Uruguay, située sur la rive nord du Río de la Plata. Elle concentre la majorité de la population et de l'activité économique du pays."),
        Question(9763, "Quel fleuve borde l'Uruguay?", listOf("Paraná", "Río de la Plata", "Paraná", "Tous les deux"), 3, "Géographie", Difficulty.HARD, explanation = "Le Rio de la Plata et le fleuve Uruguay forment la frontière ouest et sud de l'Uruguay. Le pays est bordé par ces deux cours d'eau."),
        Question(9764, "La capitale de l'Argentine est...", listOf("Córdoba", "Rosario", "Buenos Aires", "Mendoza"), 2, "Géographie", Difficulty.EASY, explanation = "Buenos Aires est la capitale et la plus grande ville d'Argentine, fondée en 1536 par l'explorateur espagnol Pedro de Mendoza."),
        Question(9765, "Quel fleuve traverse l'Argentine?", listOf("Paraná", "Río de la Plata", "Uruguay", "Tous les trois"), 3, "Géographie", Difficulty.HARD, explanation = "Le Colorado, le Paraná et le Río Negro sont les trois principaux fleuves qui traversent l'Argentine, chacun drainant une région différente du pays."),
        Question(9766, "Quel est le plus haut sommet d'Amérique du Sud?", listOf("Pic Chimborazo", "Mont Aconcagua", "Pic Huascarán", "Nevado Ojos del Salado"), 1, "Géographie", Difficulty.MEDIUM, explanation = "L'Aconcagua culmine à 6 961 mètres dans la cordillère des Andes, en Argentine, ce qui en fait le plus haut sommet d'Amérique du Sud et de l'hémisphère sud."),
        Question(9767, "La capitale du Chili est...", listOf("Valparaíso", "Concepción", "Santiago", "Valdivia"), 2, "Géographie", Difficulty.EASY, explanation = "Santiago est la capitale et la plus grande ville du Chili, située dans la vallée centrale du pays. Elle a été fondée en 1541 par le conquistador espagnol Pedro de Valdivia."),
        Question(9768, "Quel désert borde le Chili?", listOf("Désert de Sechura", "Désert d'Atacama", "Désert de Patagonie", "Pampas"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le désert d'Atacama, situé dans le nord du Chili, est l'un des plus arides au monde, bordant l'océan Pacifique."),
        Question(9769, "La capitale du Paraguay est...", listOf("Encarnación", "Ciudad del Este", "Asunción", "Villarrica"), 2, "Géographie", Difficulty.EASY, explanation = "Asunción est la capitale et la plus grande ville du Paraguay, située sur la rive gauche du fleuve Paraguay. Elle fut fondée en 1537 par les conquistadors espagnols."),
        Question(9770, "Quel fleuve traverse le Paraguay?", listOf("Paraná", "Paraguay", "Tapajós", "Tous les deux"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le fleuve Paraguay traverse le pays du même nom du nord au sud, servant d'axe majeur pour le transport et l'économie, avant de se jeter dans le Paraná."),
        Question(9771, "Quel continent a le plus de frontières terrestres?", listOf("Asie", "Amérique du Nord", "Europe", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie est le plus grand continent et partage des frontières terrestres avec l'Europe et l'Afrique, ainsi qu'avec de nombreux pays voisins, ce qui lui donne le plus grand nombre de frontières terrestres."),
        Question(9772, "Quel pays a le plus de frontières terrestres?", listOf("Russie", "Canada", "Chine", "France"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie partage des frontières terrestres avec 14 pays, incluant la Norvège, la Finlande, la Chine et la Corée du Nord, ce qui en fait le record mondial."),
        Question(9773, "Quel est le pays le plus peuplé du monde?", listOf("Inde", "Chine", "Indonésie", "Pakistan"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Inde a dépassé la Chine en 2023 pour devenir le pays le plus peuplé du monde, avec plus de 1,4 milliard d'habitants."),
        Question(9774, "Quel est le pays le moins peuplé du monde?", listOf("Vatican", "Nauru", "Tuvalu", "Palaos"), 0, "Géographie", Difficulty.HARD, explanation = "Le Vatican, avec environ 800 habitants, est une cité-État enclavée dans Rome et le siège de l'Église catholique, ce qui en fait le pays le moins peuplé du monde."),
        Question(9775, "Quel continent a le plus de pays?", listOf("Asie", "Afrique", "Amérique", "Europe"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique compte 54 pays reconnus par l'ONU, soit le plus grand nombre de tous les continents, devant l'Europe (environ 50) et l'Asie (48)."),
        Question(9776, "Quel est le plus grand désert du monde?", listOf("Arabie", "Gobi", "Sahara", "Antarctique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Sahara est le plus grand désert chaud du monde, mais si l'on considère les déserts polaires, l'Antarctique est en réalité le plus vaste."),
        Question(9777, "Quel est le plus haut sommet du monde?", listOf("K2", "Mont Everest", "Kangchenjunga", "Lhotse"), 1, "Géographie", Difficulty.EASY, explanation = "L'Everest culmine à 8 848,86 mètres d'altitude dans l'Himalaya, à la frontière entre le Népal et le Tibet. Il doit son nom au géomètre britannique George Everest."),
        Question(9778, "Quel est le plus profond océan du monde?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Océan Arctique"), 2, "Géographie", Difficulty.HARD, explanation = "L'océan Pacifique abrite la fosse des Mariannes, dont le point le plus profond, le Challenger Deep, descend à environ 11 000 mètres sous le niveau de la mer."),
        Question(9779, "Quel est le fleuve le plus long du monde?", listOf("Amazone", "Congo", "Nil", "Mississippi"), 2, "Géographie", Difficulty.EASY, explanation = "Le Nil traverse l'Afrique de l'Est sur environ 6 650 kilomètres, ce qui en fait le plus long fleuve du monde selon les mesures standard."),
        Question(9780, "Quel est le plus grand lac du monde?", listOf("Lac Baïkal", "Lac Victoria", "Lac Supérieur", "Mer Caspienne"), 3, "Géographie", Difficulty.HARD, explanation = "La mer Caspienne, bien que nommée mer, est un lac salé endoréique bordé par cinq pays. Sa superficie d'environ 371 000 km² en fait le plus grand lac du monde."),
        Question(9781, "Quel est le plus grand archipel du monde?", listOf("Hawaï", "Maldives", "Indonésie", "Philippines"), 2, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel du monde avec plus de 17 000 îles, s'étendant sur l'équateur entre l'océan Indien et l'océan Pacifique."),
        Question(9782, "Quel est le plus grand delta du monde?", listOf("Delta du Mékong", "Delta du Gange", "Delta du Nil", "Delta de l'Amazone"), 1, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange, situé principalement au Bangladesh et en Inde, est le plus grand du monde avec une superficie d'environ 100 000 km², formé par les fleuves Gange et Brahmapoutre."),
        Question(9783, "Quel est le plus grand golf du monde?", listOf("Golfe du Mexique", "Golfe du Bengale", "Golfe de Persique", "Golfe du Saint-Laurent"), 1, "Géographie", Difficulty.HARD, explanation = "Le golfe du Bengale est le plus grand golfe du monde, s'étendant sur environ 2 172 000 km² entre la péninsule indienne et l'Asie du Sud-Est."),
        Question(9784, "Quel est le plus grand détroit du monde?", listOf("Détroit de Malacca", "Détroit de Béring", "Détroit de Magellan", "Détroit de Drake"), 3, "Géographie", Difficulty.HARD, explanation = "Le détroit de Drake, entre l'Amérique du Sud et l'Antarctique, est le plus large du monde avec environ 800 km, reliant l'océan Pacifique à l'océan Atlantique."),
        Question(9785, "Quel est le plus grand glacier du monde?", listOf("Glacier Siachen", "Glacier Baltoro", "Glacier Lambert", "Inlandsis du Groenland"), 3, "Géographie", Difficulty.HARD, explanation = "L'inlandsis du Groenland est le plus grand glacier du monde, couvrant environ 1,7 million de kilomètres carrés, soit 80 % de la surface du Groenland."),
        Question(9786, "Quel est le plus grand plateau du monde?", listOf("Plateau du Tibet", "Plateau de l'Altaï", "Plateau du Colorado", "Plateau du Deccan"), 0, "Géographie", Difficulty.HARD, explanation = "Le plateau du Tibet, souvent appelé le « toit du monde », est le plus vaste et le plus haut plateau de la planète, avec une altitude moyenne dépassant 4 500 mètres."),
        Question(9787, "Quel est le plus grand bassin de sédiments du monde?", listOf("Bassin du Gange", "Bassin du Congo", "Bassin de l'Amazone", "Bassin du Mississippi"), 2, "Géographie", Difficulty.HARD, explanation = "Le bassin de l'Amazone, s'étendant sur environ 7 millions de km², est le plus grand bassin sédimentaire au monde en raison de l'immense volume de sédiments transportés par le fleuve Amazone depuis les Andes jusqu'à l'océan Atlantique."),
        Question(9788, "Quel est le plus grand port du monde?", listOf("Port de Rotterdam", "Port de Singapour", "Port de Shanghai", "Port de Hong Kong"), 2, "Géographie", Difficulty.HARD, explanation = "Le port de Shanghai est le plus grand port du monde en termes de volume de conteneurs et de trafic de marchandises depuis 2010, dépassant Singapour."),
        Question(9789, "Quel est le plus grand aéroport du monde?", listOf("Aéroport de Dubaï", "Aéroport d'Atlanta", "Aéroport de Chicago", "Aéroport de Los Angeles"), 1, "Géographie", Difficulty.HARD, explanation = "L'aéroport international Hartsfield-Jackson d'Atlanta est le plus fréquenté au monde en nombre de passagers depuis 1998, grâce à son rôle de hub majeur pour Delta Air Lines et sa situation géographique stratégique aux États-Unis."),
        Question(9790, "Quel est le plus grand stade du monde?", listOf("Stade de Michigan", "Stade Beaver", "Stade Tiger", "Stade de Rungrado"), 3, "Géographie", Difficulty.HARD, explanation = "Le Stade de Rungrado, situé à Pyongyang en Corée du Nord, peut accueillir environ 114 000 spectateurs, ce qui en fait le plus grand stade du monde par sa capacité."),
        Question(9791, "Quel est le plus grand musée du monde?", listOf("Musée du Louvre", "Musée du Vatican", "Musée de l'Hermitage", "Musée d'art moderne"), 0, "Géographie", Difficulty.HARD, explanation = "Le Louvre à Paris est le plus grand musée du monde par sa superficie totale de 72 735 mètres carrés, abritant des œuvres comme la Joconde et la Vénus de Milo."),
        Question(9792, "Quel est le plus grand zoo du monde?", listOf("Zoo de San Diego", "Zoo du Bronx", "Zoo de Berlin", "Zoo de San Antonio"), 0, "Géographie", Difficulty.HARD, explanation = "Le zoo de San Diego est considéré comme le plus grand zoo du monde en termes de superficie et de collection d'animaux, avec plus de 12 000 spécimens représentant 650 espèces."),
        Question(9793, "Quel est le plus grand château du monde?", listOf("Château de Versailles", "Château de Prague", "Château de Windsor", "Château du Kremlin"), 2, "Géographie", Difficulty.HARD, explanation = "Le château de Windsor, résidence royale en Angleterre, est le plus grand château habité du monde avec plus de 1 000 pièces. Il est également le plus ancien palais occupé en continu d'Europe."),
        Question(9794, "Quel est le plus grand temple du monde?", listOf("Temples d'Angkor Vat", "Temple du Mont-Athos", "Temple du Kailasa", "Temple Meenakshi"), 0, "Géographie", Difficulty.HARD, explanation = "Angkor Vat, au Cambodge, est le plus grand temple du monde avec une superficie de 162,6 hectares. Il a été construit au XIIe siècle par le roi Suryavarman II."),
        Question(9795, "Quel est le plus grand désert de glace du monde?", listOf("Inlandsis du Groenland", "Glacier Lambert", "Plateau du Tibet", "Inlandsis de l'Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'inlandsis de l'Antarctique est le plus grand désert de glace car il recouvre 98 % du continent avec une épaisseur moyenne de 2 160 mètres, formant une calotte glaciaire immense et aride."),
        Question(9796, "Quel est le plus grand parc national du monde?", listOf("Parc de Yellowstone", "Parc de Serengeti", "Parc du Groenland du Nord-Est", "Parc de la Vallée de la Mort"), 2, "Géographie", Difficulty.HARD, explanation = "Le Parc national du Groenland du Nord-Est s'étend sur environ 972 000 km², ce qui en fait le plus vaste parc national au monde, couvrant une grande partie du nord-est du Groenland."),
        Question(9797, "Quel est le plus grand pays sans accès à la mer?", listOf("Kazakhstan", "Mongolie", "Afghanistan", "Ouganda"), 0, "Géographie", Difficulty.HARD, explanation = "Le Kazakhstan est le plus grand pays enclavé du monde, avec une superficie de 2,7 millions de km², dépassant ainsi la Mongolie et le Niger."),
        Question(9798, "Quel est le pays le plus au nord du monde?", listOf("Groenland", "Islande", "Norvège", "Canada"), 0, "Géographie", Difficulty.HARD, explanation = "Le Groenland est un territoire autonome du Danemark, et son point le plus septentrional, le cap Morris Jesup, est la terre la plus proche du pôle Nord."),
        Question(9799, "Quel est le pays le plus au sud du monde?", listOf("Chili", "Argentine", "Nouvelle-Zélande", "Australie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Argentine abrite l'île de Hornos, où se situe le cap Horn, point le plus méridional des terres émergées du continent américain."),
        Question(9800, "Quel est le pays le plus à l'est du monde?", listOf("Nouvelle-Zélande", "Japon", "Océanie", "Kiribati"), 3, "Géographie", Difficulty.HARD, explanation = "Kiribati est le pays le plus à l'est car il s'étend dans l'océan Pacifique jusqu'à la ligne de changement de date, incluant les îles de la Ligne qui sont les premières à voir le jour."),
        Question(9801, "Quel est le pays le plus à l'ouest du monde?", listOf("Canada", "États-Unis", "Samoa américaines", "Îles Aléoutiennes"), 2, "Géographie", Difficulty.HARD, explanation = "Les Samoa américaines sont situées juste à l'ouest de la ligne de changement de date, ce qui en fait le territoire le plus à l'ouest du monde en termes de fuseau horaire."),
        Question(9802, "Quel est le plus grand pays du monde par superficie?", listOf("Canada", "Chine", "Russie", "États-Unis"), 2, "Géographie", Difficulty.EASY, explanation = "La Russie s'étend sur plus de 17 millions de kilomètres carrés, soit environ 11% des terres émergées, ce qui en fait le plus vaste pays du monde devant le Canada et les États-Unis."),
        Question(9803, "Quel est le deuxième plus grand pays du monde par superficie?", listOf("Chine", "Canada", "Russie", "États-Unis"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Canada est le deuxième plus vaste pays du monde après la Russie, avec une superficie d'environ 9,98 millions de kilomètres carrés."),
        Question(9804, "Quel est le troisième plus grand pays du monde par superficie?", listOf("Chine", "Canada", "Russie", "États-Unis"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Les États-Unis sont le troisième plus grand pays du monde avec environ 9,8 millions de km², derrière la Russie et le Canada."),
        Question(9805, "Quel est le quatrième plus grand pays du monde par superficie?", listOf("Chine", "Canada", "Russie", "États-Unis"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Les États-Unis se classent au quatrième rang mondial avec une superficie d'environ 9,8 millions de km², derrière la Russie, le Canada et la Chine."),
        Question(9806, "Quel est le cinquième plus grand pays du monde par superficie?", listOf("Brésil", "Australie", "Inde", "Kazakhstan"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le Brésil est le cinquième plus grand pays du monde avec environ 8,5 millions de km², derrière la Russie, le Canada, les États-Unis et la Chine."),
        Question(9807, "Quel est le sixième plus grand pays du monde par superficie?", listOf("Brésil", "Australie", "Inde", "Kazakhstan"), 1, "Géographie", Difficulty.MEDIUM, explanation = "L'Australie est le sixième plus grand pays du monde avec environ 7,7 millions de km², derrière la Russie, le Canada, les États-Unis, la Chine et le Brésil."),
        Question(9808, "Quel est le septième plus grand pays du monde par superficie?", listOf("Brésil", "Australie", "Inde", "Kazakhstan"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'Inde est le septième plus grand pays du monde avec une superficie d'environ 3,287 millions de kilomètres carrés, derrière la Russie, le Canada, les États-Unis, la Chine, le Brésil et l'Australie."),
        Question(9809, "Quel est le huitième plus grand pays du monde par superficie?", listOf("Brésil", "Australie", "Inde", "Kazakhstan"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le Kazakhstan est le neuvième plus vaste pays du monde, avec une superficie d'environ 2,7 millions de km², derrière l'Argentine."),
        Question(9810, "Quel est le neuvième plus grand pays du monde par superficie?", listOf("Groenland", "Mexique", "Indonésie", "Libye"), 2, "Géographie", Difficulty.HARD, explanation = "Avec une superficie d'environ 1,9 million de km², l'Indonésie se classe neuvième, principalement grâce à son vaste territoire maritime et ses nombreuses îles."),
        Question(9811, "Quel est le dixième plus grand pays du monde par superficie?", listOf("Groenland", "Mexique", "Libye", "Pérou"), 2, "Géographie", Difficulty.HARD, explanation = "La Libye est le dixième plus grand pays du monde avec une superficie d'environ 1,76 million de km², principalement couverte par le désert du Sahara."),
        Question(9812, "Quel est le pays le plus densément peuplé du monde (excluant les microstats)?", listOf("Singapour", "Bangladesh", "Malaisie", "Thaïlande"), 1, "Géographie", Difficulty.HARD, explanation = "Le Bangladesh compte plus de 170 millions d'habitants sur un territoire de 147 570 km², soit une densité d'environ 1 265 personnes par km²."),
        Question(9813, "Quel est le pays le moins densément peuplé du monde?", listOf("Mongolie", "Mauritanie", "Australie", "Canada"), 0, "Géographie", Difficulty.HARD, explanation = "La Mongolie possède une très faible densité de population d'environ 2 habitants par km² en raison de ses vastes steppes arides et de son climat continental extrême."),
        Question(9814, "Quel est le plus grand pays sans capitale établie?", listOf("Suisse", "Australie", "Nouvelle-Zélande", "Aucun"), 3, "Géographie", Difficulty.HARD, explanation = "Tous les pays reconnus par l'ONU possèdent une capitale officielle. Aucun État souverain ne fonctionne sans un lieu désigné comme siège de son gouvernement."),
        Question(9815, "Quel est le pays avec le plus de capitales?", listOf("Afrique du Sud", "Suisse", "Australie", "Pays-Bas"), 0, "Géographie", Difficulty.HARD, explanation = "L'Afrique du Sud possède trois capitales officielles : Pretoria (administrative), Le Cap (législative) et Bloemfontein (judiciaire), ce qui en fait le pays avec le plus de capitales au monde."),
        Question(9816, "Quel est le pays avec le plus de fuseaux horaires?", listOf("Australie", "Russie", "France", "États-Unis"), 2, "Géographie", Difficulty.HARD, explanation = "La France possède le plus grand nombre de fuseaux horaires au monde (12, voire 13 avec l'heure d'été) grâce à ses territoires d'outre-mer répartis sur tous les océans."),
        Question(9817, "Quel est le pays avec le plus de voisins terrestres?", listOf("Russie", "Chine", "France", "Allemagne"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie partage ses frontières terrestres avec 14 pays, incluant la Norvège, la Finlande, la Chine et la Mongolie, ce qui en fait le pays avec le plus de voisins terrestres au monde."),
        Question(9818, "Quel est le pays avec le moins de voisins terrestres?", listOf("Islande", "Nouvelle-Zélande", "Japon", "Australie"), 1, "Géographie", Difficulty.HARD, explanation = "La Nouvelle-Zélande est un pays insulaire, sans aucune frontière terrestre avec d'autres pays, ce qui en fait celui avec le moins de voisins terrestres."),
        Question(9819, "Quel est le pays le plus montagneux du monde?", listOf("Népal", "Suisse", "Kirghizistan", "Pérou"), 2, "Géographie", Difficulty.HARD, explanation = "Le Kirghizistan est considéré comme le pays le plus montagneux du monde car plus de 90% de son territoire est recouvert par les chaînes du Tian Shan et du Pamir, avec une altitude moyenne dépassant 2 700 mètres."),
        Question(9820, "Quel est le pays le plus plat du monde?", listOf("Belgique", "Pays-Bas", "Danemark", "Moldavie"), 1, "Géographie", Difficulty.HARD, explanation = "Avec une altitude moyenne de seulement 30 mètres et un point culminant à 321 mètres, les Pays-Bas sont le pays le plus plat du monde, en grande partie grâce à leur topographie de polders et de plaines côtières."),
        Question(9821, "Quel est le pays le plus boisé du monde?", listOf("Russie", "Brésil", "Inde", "Canada"), 1, "Géographie", Difficulty.HARD, explanation = "Le Brésil possède la plus grande forêt tropicale du monde, l'Amazonie, qui couvre environ 60 % de son territoire."),
        Question(9822, "Quel est le pays le plus désertique du monde?", listOf("Egypte", "Libye", "Chine", "Australie"), 1, "Géographie", Difficulty.HARD, explanation = "La Libye est considérée comme le pays le plus désertique du monde car plus de 95% de son territoire est couvert par le désert du Sahara, avec une très faible densité de population et des précipitations annuelles infimes."),
        Question(9823, "Quel est le pays le plus humide du monde?", listOf("Colombie", "Malaisie", "Brésil", "Nouvelle-Zélande"), 0, "Géographie", Difficulty.HARD, explanation = "La Colombie détient ce record en raison des précipitations extrêmes dans la région du Chocó, où la ville de Lloró reçoit en moyenne plus de 13 000 mm de pluie par an."),
        Question(9824, "Quel est le pays le plus sec du monde?", listOf("Pérou", "Égypte", "Chili", "Atacama"), 1, "Géographie", Difficulty.HARD, explanation = "L'Égypte est considérée comme le pays le plus sec du monde en raison de son climat désertique, avec des précipitations annuelles moyennes inférieures à 20 mm dans la plupart des régions."),
        Question(9825, "Quel est le pays le plus chaud du monde?", listOf("Soudan", "Arabie Saoudite", "Djibouti", "Mauritanie"), 2, "Géographie", Difficulty.HARD, explanation = "Djibouti détient la température moyenne annuelle la plus élevée au monde, autour de 30°C, en raison de son climat désertique et de sa situation géographique près de l'équateur."),
        Question(9826, "Quel est le pays le plus froid du monde?", listOf("Groenland", "Sibérie", "Antarctique", "Canada"), 2, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est le continent le plus froid du monde, avec des températures record descendant jusqu'à -89,2°C. Il n'est pas un pays, mais un territoire régi par un traité international."),
        Question(9827, "Quel est le pays avec le plus de lacs?", listOf("Suède", "Finlande", "Canada", "Russie"), 2, "Géographie", Difficulty.HARD, explanation = "Le Canada compte plus de deux millions de lacs, soit environ 60% des lacs du monde, en raison de son histoire glaciaire et de son vaste territoire."),
        Question(9828, "Quel est le pays avec le plus de rivières?", listOf("Brésil", "Inde", "Chine", "Russie"), 0, "Géographie", Difficulty.HARD, explanation = "Le Brésil possède le plus grand réseau hydrographique du monde en raison de l'Amazonie et de ses nombreux affluents, totalisant plus de 12 000 rivières."),
        Question(9829, "Quel est le pays avec le plus de volcans?", listOf("Indonésie", "Chili", "Japon", "Mexique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Indonésie se trouve sur la ceinture de feu du Pacifique, une zone de forte activité tectonique, et compte plus de 130 volcans actifs, soit le plus grand nombre au monde."),
        Question(9830, "Quel est le pays avec le plus de tremblements de terre?", listOf("Japon", "Indonésie", "Chili", "Pérou"), 1, "Géographie", Difficulty.HARD, explanation = "L'Indonésie se situe sur la ceinture de feu du Pacifique, une zone de forte activité tectonique où plusieurs plaques se rencontrent, provoquant de nombreux séismes."),
        Question(9831, "Quel est le pays avec le plus de glaciers?", listOf("Norvège", "Nouvelle-Zélande", "Groenland", "Canada"), 3, "Géographie", Difficulty.HARD, explanation = "Le Canada possède le plus grand nombre de glaciers au monde, principalement concentrés dans l'Arctique et les montagnes Rocheuses, avec environ 200 000 glaciers recensés."),
        Question(9832, "Quel est le pays avec le plus de îles?", listOf("Suède", "Finlande", "Norvège", "Canada"), 2, "Géographie", Difficulty.HARD, explanation = "La Norvège possède le plus grand nombre d'îles au monde, avec environ 50 000 îles répertoriées le long de son littoral découpé par les fjords."),
        Question(9833, "Quel est le pays avec le plus de forêts tropicales?", listOf("Indonésie", "Pérou", "Brésil", "Congo"), 2, "Géographie", Difficulty.HARD, explanation = "Le Brésil abrite environ 60% de la forêt amazonienne, la plus grande forêt tropicale du monde, ce qui en fait le pays avec la plus grande superficie de ce type de forêt."),
        Question(9834, "Quel est le pays avec le plus de deserts?", listOf("Australie", "Russie", "États-Unis", "Égypte"), 0, "Géographie", Difficulty.HARD, explanation = "L'Australie est le pays qui possède la plus grande superficie de déserts, avec environ 70% de son territoire classé comme aride ou semi-aride."),
        Question(9835, "Quel est le plus grand pays multilingue du monde?", listOf("Inde", "Suisse", "Belgique", "Cameroun"), 0, "Géographie", Difficulty.HARD, explanation = "L'Inde compte 22 langues officiellement reconnues et des centaines de dialectes, ce qui en fait le pays avec la plus grande diversité linguistique au monde."),
        Question(9836, "Quel est le pays avec le plus de religions?", listOf("Inde", "Chine", "États-Unis", "Brésil"), 0, "Géographie", Difficulty.HARD, explanation = "L'Inde abrite une diversité religieuse exceptionnelle avec l'hindouisme, l'islam, le christianisme, le sikhisme, le bouddhisme et le jaïnisme, entre autres. Cette pluralité est reconnue et protégée par la constitution indienne."),
        Question(9837, "Quel est le pays avec le plus de minorités?", listOf("Inde", "Indonésie", "Nigeria", "Chine"), 0, "Géographie", Difficulty.HARD, explanation = "L'Inde abrite des centaines de groupes linguistiques, ethniques et religieux distincts, reconnus officiellement comme minorités, ce qui en fait le pays le plus diversifié au monde à cet égard."),
        Question(9838, "Quel est le pays avec le plus de traditions culturelles?", listOf("Inde", "Chine", "Japon", "Italie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Inde possède une diversité culturelle exceptionnelle avec des traditions variant selon les régions, langues et religions, ce qui lui confère le plus grand nombre de traditions culturelles recensées."),
        Question(9839, "Quel est le plus grand pays en développement du monde?", listOf("Inde", "Chine", "Brésil", "Indonésie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Inde est considérée comme le plus grand pays en développement en raison de sa population massive et de son statut économique émergent, bien qu'elle soit encore classée comme un pays à revenu intermédiaire."),
        Question(9840, "Quel est le plus grand pays insulaire du monde?", listOf("Philippines", "Indonésie", "Japon", "Nouvelle-Zélande"), 1, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel du monde avec plus de 17 000 îles, ce qui en fait le plus grand pays insulaire par superficie et population."),
        Question(9841, "Quel est le plus grand pays sans ressources naturelles?", listOf("Singapour", "Luxembourg", "Liechtenstein", "Suisse"), 0, "Géographie", Difficulty.HARD, explanation = "Singapour est une cité-État dépourvue de ressources naturelles comme le pétrole ou les minerais, mais elle a bâti sa richesse sur le commerce et la finance."),
        Question(9842, "Quel est le plus grand désert côtier du monde?", listOf("Atacama", "Namib", "Sahara", "Arabie"), 1, "Géographie", Difficulty.HARD, explanation = "Le désert du Namib, situé le long de la côte atlantique de la Namibie, est considéré comme le plus ancien désert du monde et le plus grand désert côtier."),
        Question(9843, "Quel est le plus grand delta fluvial du monde?", listOf("Delta du Gange", "Delta du Mékong", "Delta de l'Amazone", "Delta du Nil"), 0, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange, situé principalement au Bangladesh et en Inde, est le plus grand delta fluvial du monde en superficie, formé par les fleuves Gange et Brahmapoutre."),
        Question(9844, "Quel est le plus grand estuaire du monde?", listOf("Estuaire du Gange", "Estuaire de l'Amazone", "Estuaire de l'Orénoque", "Estuaire de la Tamise"), 0, "Géographie", Difficulty.HARD, explanation = "L'estuaire du Gange, situé au Bangladesh, est le plus vaste du monde en superficie. Il se forme à la confluence du Gange et du Brahmapoutre avant de se jeter dans le golfe du Bengale."),
        Question(9845, "Quel est le plus grand fjord du monde?", listOf("Fjord de Sognefjord", "Fjord de Hardangerfjord", "Fjord de Scorsby Sund", "Fjord de Geirangerfjord"), 2, "Géographie", Difficulty.HARD, explanation = "Le Scoresby Sund, situé au Groenland, est le plus grand fjord du monde avec une longueur de 350 kilomètres et une profondeur atteignant 1 450 mètres."),
        Question(9846, "Quel est le plus grand geyser du monde?", listOf("Great Geyser", "Strokkur", "Old Faithful", "Steamboat Geyser"), 3, "Géographie", Difficulty.HARD, explanation = "Le Steamboat Geyser, situé dans le parc national de Yellowstone aux États-Unis, détient le record du plus haut geyser actif, avec des éruptions pouvant atteindre 90 mètres."),
        Question(9847, "Quel est le plus grand cañon du monde?", listOf("Canyonlands", "Zion Canyon", "Grand Canyon", "Palo Duro Canyon"), 2, "Géographie", Difficulty.HARD, explanation = "Le Grand Canyon, situé dans l'Arizona aux États-Unis, est le plus célèbre et le plus vaste canyon du monde, creusé par le fleuve Colorado sur des millions d'années."),
        Question(9848, "Quel est le plus grand îlot du monde?", listOf("Île de Baffin", "Île Greenland", "Île Nouvelle-Guinée", "Île de Sumatra"), 1, "Géographie", Difficulty.HARD, explanation = "Le Groenland est la plus grande île du monde avec une superficie d'environ 2,16 millions de km², bien qu'il soit souvent considéré comme un territoire danois plutôt qu'un continent."),
        Question(9849, "Quel est le plus petit continent du monde?", listOf("Europe", "Asie", "Afrique", "Océanie"), 3, "Géographie", Difficulty.EASY, explanation = "L'Océanie est le plus petit continent en superficie, comprenant l'Australie, la Nouvelle-Zélande et les îles du Pacifique."),
        Question(9850, "Quel est le continent le plus peuplé?", listOf("Afrique", "Asie", "Europe", "Amérique du Nord"), 1, "Géographie", Difficulty.EASY, explanation = "L'Asie abrite environ 60% de la population mondiale, avec des pays comme la Chine et l'Inde dépassant chacun le milliard d'habitants."),
        Question(9851, "Quel est le continent le plus froid?", listOf("Asie", "Antarctique", "Amérique du Nord", "Groenland"), 1, "Géographie", Difficulty.EASY, explanation = "L'Antarctique détient le record de la température la plus basse sur Terre, avec des températures pouvant descendre en dessous de -90°C. Sa calotte glaciaire et son altitude élevée en font le continent le plus froid."),
        Question(9852, "Quel est le continent le plus sec?", listOf("Afrique", "Asie", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "Bien que l'Antarctique soit recouvert de glace, il reçoit très peu de précipitations, ce qui en fait un désert polaire et le continent le plus sec de la planète."),
        Question(9853, "Quel est le continent le plus montagneux?", listOf("Asie", "Amérique du Nord", "Amérique du Sud", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite les plus hauts sommets du monde, dont l'Himalaya et le plateau tibétain, ce qui en fait le continent le plus montagneux en termes d'altitude moyenne et de relief."),
        Question(9854, "Quel est le continent le plus boisé?", listOf("Asie", "Afrique", "Amérique du Sud", "Amérique du Nord"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud abrite la plus grande forêt tropicale du monde, l'Amazonie, qui représente environ 40% de la superficie forestière du continent."),
        Question(9855, "Quel est le continent le plus densément peuplé?", listOf("Asie", "Afrique", "Europe", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite plus de 60% de la population mondiale, avec des pays très densément peuplés comme la Chine et l'Inde, ce qui en fait le continent le plus densément peuplé."),
        Question(9856, "Quel est le continent le moins densément peuplé?", listOf("Antarctique", "Océanie", "Asie", "Amérique du Nord"), 0, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est le continent le moins densément peuplé car il n'a pas de population permanente, seulement des chercheurs et du personnel de soutien dans des stations scientifiques."),
        Question(9857, "Quel est le continent avec le plus de pays?", listOf("Asie", "Afrique", "Europe", "Amérique"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique compte 54 pays reconnus par l'ONU, ce qui en fait le continent le plus fragmenté politiquement, devant l'Europe et l'Asie."),
        Question(9858, "Quel est le continent avec le moins de pays?", listOf("Antarctique", "Océanie", "Amérique du Sud", "Europe"), 0, "Géographie", Difficulty.HARD, explanation = "L'Antarctique n'est pas un pays et n'a pas de population permanente, ce qui en fait le continent avec le moins de pays, soit zéro."),
        Question(9859, "Quel est le continent le plus jeune géologiquement?", listOf("Asie", "Amérique du Nord", "Antarctique", "Océanie"), 3, "Géographie", Difficulty.HARD, explanation = "L'Océanie est le continent le plus jeune car il repose sur des plaques tectoniques en formation active, avec des terres émergées récentes comme la Nouvelle-Guinée et la Nouvelle-Zélande."),
        Question(9860, "Quel est le continent le plus ancien géologiquement?", listOf("Afrique", "Asie", "Amérique du Sud", "Antarctique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Afrique possède les plus anciennes roches datées sur Terre, avec des formations comme le craton du Kaapvaal vieux de plus de 3,6 milliards d'années."),
        Question(9861, "Quel est le continent avec le plus grand nombre de tremblements de terre?", listOf("Asie", "Amérique du Nord", "Amérique du Sud", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie est le continent le plus touché par les séismes car elle est située sur la ceinture de feu du Pacifique et la collision des plaques tectoniques y est très active."),
        Question(9862, "Quel est le continent avec le plus de volcans?", listOf("Asie", "Amérique du Nord", "Amérique du Sud", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite environ 60 % des volcans actifs du monde, notamment le long de la ceinture de feu du Pacifique, ce qui en fait le continent le plus volcanique."),
        Question(9863, "Quel est le continent avec le plus de glaciers?", listOf("Asie", "Amérique du Nord", "Antarctique", "Europe"), 2, "Géographie", Difficulty.HARD, explanation = "L'Antarctique contient environ 90 % des glaces mondiales, avec une calotte glaciaire qui s'étend sur 14 millions de km², ce qui en fait le continent le plus glaciaire."),
        Question(9864, "Quel est le continent avec le plus de déserts?", listOf("Asie", "Afrique", "Amérique du Nord", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite les plus grandes étendues désertiques du monde, comme le désert de Gobi et le désert d'Arabie, ce qui lui donne le plus grand nombre de déserts parmi tous les continents."),
        Question(9865, "Quel est le continent avec le plus de forêts tropicales?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud abrite la plus grande forêt tropicale du monde, l'Amazonie, qui s'étend sur neuf pays et représente environ la moitié des forêts tropicales restantes sur Terre."),
        Question(9866, "Quel est le continent avec le plus de savanes?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique abrite la plus vaste étendue de savanes au monde, notamment le célèbre Serengeti, grâce à son climat tropical alternant saisons sèches et humides."),
        Question(9867, "Quel est le continent avec le plus de toundras?", listOf("Asie", "Amérique du Nord", "Antarctique", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "La toundra arctique couvre une vaste partie du nord du Canada et de l'Alaska, faisant de l'Amérique du Nord le continent possédant la plus grande superficie de ce biome."),
        Question(9868, "Quel est le continent avec le plus de lacs d'eau douce?", listOf("Asie", "Amérique du Nord", "Europe", "Afrique"), 1, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord abrite plus de lacs d'eau douce que tous les autres continents réunis, principalement en raison des glaciers qui ont creusé des bassins lacustres lors de la dernière période glaciaire."),
        Question(9869, "Quel est le continent avec le plus de rivières?", listOf("Asie", "Amérique du Sud", "Afrique", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud abrite le bassin amazonien, le plus vaste réseau fluvial du monde, avec des milliers d'affluents comme l'Amazone, l'Orénoque et le Paraná."),
        Question(9870, "Quel est le continent avec le plus de côtes?", listOf("Asie", "Océanie", "Amérique du Nord", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie possède le plus long littoral du monde, avec environ 62 000 kilomètres de côtes, en raison de sa vaste superficie et de ses nombreuses péninsules et îles."),
        Question(9871, "Quel est le continent avec le plus d'îles?", listOf("Asie", "Océanie", "Europe", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie possède le plus grand nombre d'îles au monde, notamment grâce à des archipels comme l'Indonésie, les Philippines et le Japon, qui comptent des milliers d'îles chacun."),
        Question(9872, "Quel est le continent avec la plus grande biodiversité?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud abrite la plus grande biodiversité mondiale grâce à l'Amazonie, qui couvre près de 40% du continent et concentre une immense variété d'espèces animales et végétales."),
        Question(9873, "Quel est le continent avec le plus d'espèces menacées?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite la plus grande diversité d'espèces animales et végétales, mais aussi les pressions humaines les plus fortes, comme la déforestation et le braconnage, ce qui en fait le continent comptant le plus d'espèces menacées."),
        Question(9874, "Quel est le continent le plus riche en minéraux?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique possède d'importants gisements de diamants, d'or, de cobalt et de coltan, ce qui en fait le continent le plus riche en ressources minérales."),
        Question(9875, "Quel est le continent le plus riche en pétrole?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie, et plus précisément le Moyen-Orient, concentre les plus grandes réserves prouvées de pétrole, notamment en Arabie saoudite, en Irak et au Koweït."),
        Question(9876, "Quel est le continent le plus riche en gaz naturel?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie, notamment via le Qatar, l’Iran et la Russie, détient les plus grandes réserves prouvées de gaz naturel au monde."),
        Question(9877, "Quel est le continent le plus riche en métaux précieux?", listOf("Asie", "Afrique", "Amérique du Sud", "Amérique du Nord"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique possède d'importants gisements d'or, de diamants et de platine, notamment en Afrique du Sud, au Botswana et en République démocratique du Congo."),
        Question(9878, "Quel est le continent le plus riche en ressources agricoles?", listOf("Asie", "Afrique", "Amérique du Sud", "Amérique du Nord"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud possède d'immenses terres fertiles comme le Cerrado brésilien et la Pampa argentine, et est un leader mondial pour le soja, le café et la viande bovine."),
        Question(9879, "Quel est le continent le plus riche en ressources hydrologiques?", listOf("Asie", "Afrique", "Amérique du Sud", "Amérique du Nord"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Sud possède le plus grand fleuve du monde en volume d'eau, l'Amazone, ainsi que d'immenses nappes phréatiques comme l'aquifère Guarani."),
        Question(9880, "Quel est le continent le plus riche en ressources éoliennes?", listOf("Asie", "Amérique du Nord", "Europe", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord possède les plus vastes étendues de plaines et de côtes exposées à des vents forts et constants, notamment dans les Grandes Plaines et au large des côtes atlantiques."),
        Question(9881, "Quel est le continent le plus riche en ressources solaires?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique reçoit le plus d'heures d'ensoleillement par an de tous les continents, avec un potentiel solaire particulièrement élevé dans le désert du Sahara."),
        Question(9882, "Quel est le continent le plus riche en ressources géothermales?", listOf("Asie", "Amérique du Nord", "Europe", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie possède la plus grande concentration de volcans et de zones tectoniques actives, notamment dans la ceinture de feu du Pacifique, ce qui en fait le continent le plus riche en ressources géothermales."),
        Question(9883, "Quel est le continent le plus développé?", listOf("Asie", "Afrique", "Europe", "Océanie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Europe est considérée comme le continent le plus développé en raison de son indice de développement humain élevé, de son économie avancée et de ses infrastructures modernes."),
        Question(9884, "Quel est le continent le moins développé?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique est considérée comme le continent le moins développé en raison de ses faibles indicateurs économiques, sociaux et d'infrastructures, comme le PIB par habitant et l'accès aux soins."),
        Question(9885, "Quel est le continent avec le plus grand PIB?", listOf("Asie", "Afrique", "Europe", "Amérique du Nord"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite des économies majeures comme la Chine, le Japon et l'Inde, ce qui lui confère le PIB total le plus élevé, dépassant l'Amérique du Nord et l'Europe."),
        Question(9886, "Quel est le continent avec le plus petit PIB?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 2, "Géographie", Difficulty.HARD, explanation = "L'Océanie a le plus petit PIB total en raison de sa faible population et de ses économies insulaires peu industrialisées, loin derrière les autres continents."),
        Question(9887, "Quel est le continent avec le plus grand PIB par capita?", listOf("Asie", "Europe", "Amérique du Nord", "Océanie"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord possède le PIB par habitant le plus élevé grâce aux économies puissantes des États-Unis et du Canada, ainsi qu'à leur forte productivité et leurs ressources abondantes."),
        Question(9888, "Quel est le continent avec le plus petit PIB par capita?", listOf("Asie", "Afrique", "Amérique du Sud", "Océanie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Afrique a le PIB par capita le plus faible en raison de nombreux pays en développement, de conflits et d'une infrastructure économique limitée."),
        Question(9889, "Quel est le continent avec le plus grand commerce international?", listOf("Asie", "Europe", "Amérique du Nord", "Océanie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie domine le commerce international grâce à des puissances économiques comme la Chine et le Japon, et abrite les plus grands ports du monde."),
        Question(9890, "Quel est le continent avec le plus petit commerce international?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 2, "Géographie", Difficulty.HARD, explanation = "L'Océanie regroupe des îles dispersées et peu peuplées, avec des économies souvent isolées et de petite taille, ce qui limite son volume d'échanges mondiaux."),
        Question(9891, "Quel est le continent avec le plus de routes?", listOf("Asie", "Europe", "Amérique du Nord", "Afrique"), 1, "Géographie", Difficulty.HARD, explanation = "L'Europe possède le réseau routier le plus dense au monde, avec des infrastructures très développées dans la plupart de ses pays."),
        Question(9892, "Quel est le continent avec le moins de routes?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est un continent inhabité en permanence, sans réseau routier organisé, à l'exception de quelques pistes temporaires près des bases scientifiques."),
        Question(9893, "Quel est le continent avec le plus de chemins de fer?", listOf("Asie", "Europe", "Amérique du Nord", "Afrique"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord possède le plus long réseau ferroviaire au monde, notamment grâce aux États-Unis qui comptent environ 250 000 km de voies ferrées, principalement utilisées pour le transport de marchandises."),
        Question(9894, "Quel est le continent avec le moins de chemins de fer?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est un continent inhabité en permanence, sans réseau ferroviaire significatif, contrairement aux autres continents qui possèdent des infrastructures de transport développées."),
        Question(9895, "Quel est le continent avec le plus d'aéroports?", listOf("Asie", "Europe", "Amérique du Nord", "Afrique"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord possède le plus grand nombre d'aéroports au monde, notamment grâce aux États-Unis, qui comptent à eux seuls des milliers d'aéroports, dont les plus fréquentés comme Atlanta et Chicago."),
        Question(9896, "Quel est le continent avec le moins d'aéroports?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique compte très peu d'aéroports en raison de son climat extrême et de l'absence de population permanente, avec principalement des pistes de glace utilisées pour la recherche scientifique."),
        Question(9897, "Quel est le continent avec le plus de ports?", listOf("Asie", "Europe", "Amérique du Nord", "Afrique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite les plus grands ports du monde, comme Shanghai et Singapour, et concentre plus de la moitié du trafic maritime mondial en raison de son rôle central dans le commerce international."),
        Question(9898, "Quel est le continent avec le moins de ports?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est presque entièrement entouré de glace et de banquise, ce qui rend la construction et l'exploitation de ports extrêmement difficiles, contrairement aux autres continents habités."),
        Question(9899, "Quel est le continent avec le plus de frontières internationales?", listOf("Asie", "Afrique", "Europe", "Amérique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie compte 57 pays et de nombreuses chaînes de montagnes, fleuves et zones historiques qui créent un grand nombre de frontières terrestres, dépassant tous les autres continents."),
        Question(9900, "Quel est le continent avec le moins de frontières internationales?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique n'a pas de frontières internationales car il est régi par le Traité sur l'Antarctique, qui gèle les revendications territoriales et interdit toute activité militaire."),
        Question(9901, "Quel est le continent avec le plus de zones protégées?", listOf("Asie", "Afrique", "Amérique du Nord", "Europe"), 2, "Géographie", Difficulty.HARD, explanation = "L'Amérique du Nord compte le plus grand nombre de zones protégées au monde, incluant de vastes parcs nationaux comme ceux des États-Unis et du Canada."),
        Question(9902, "Quel est le continent avec le plus de villes millionnaires?", listOf("Asie", "Afrique", "Europe", "Amérique du Nord"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite les plus grandes mégalopoles mondiales comme Tokyo, Shanghai et Delhi, et concentre plus de la moitié des villes de plus d'un million d'habitants en raison de sa forte densité de population et de son urbanisation rapide."),
        Question(9903, "Quel est le continent avec le moins de villes millionnaires?", listOf("Asie", "Afrique", "Océanie", "Antarctique"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique est un continent sans population permanente, ce qui explique l'absence totale de villes millionnaires."),
        Question(9904, "Quel est le continent avec la plus grande mégalopole?", listOf("Asie", "Afrique", "Europe", "Amérique du Nord"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie abrite la plus grande mégalopole du monde, le Japon, avec la région du Grand Tokyo qui compte plus de 37 millions d'habitants."),
        Question(9905, "Quel est le continent avec le plus de conflits territoriaux?", listOf("Asie", "Afrique", "Amérique du Sud", "Europe"), 0, "Géographie", Difficulty.HARD, explanation = "L'Asie concentre de nombreux conflits territoriaux en raison de sa densité de population, de ses frontières héritées de la colonisation et de ses ressources stratégiques, comme en mer de Chine méridionale ou au Cachemire."),
        Question(9906, "Quel pays a la plus grande capacité hydroélectrique du monde?", listOf("Brésil", "Canada", "Chine", "Russie"), 0, "Géographie", Difficulty.HARD, explanation = "Le Brésil possède la plus grande capacité hydroélectrique installée au monde grâce à ses nombreux fleuves puissants, dont l'Amazone, et à des barrages majeurs comme Itaipu."),
        Question(9907, "Quel pays a la plus grande capacité nucléaire du monde?", listOf("États-Unis", "France", "Russie", "Chine"), 0, "Géographie", Difficulty.HARD, explanation = "Les États-Unis possèdent le plus grand parc de réacteurs nucléaires en activité, avec environ 94 réacteurs, et une capacité installée totale de près de 100 gigawatts."),
        Question(9908, "Quel pays a la plus grande capacité éolienne du monde?", listOf("Allemagne", "Chine", "États-Unis", "Inde"), 1, "Géographie", Difficulty.HARD, explanation = "La Chine possède la plus grande capacité éolienne installée au monde, dépassant largement les autres pays grâce à ses vastes parcs éoliens terrestres et offshore."),
        Question(9909, "Quel pays a la plus grande capacité solaire du monde?", listOf("Allemagne", "Chine", "Japon", "États-Unis"), 1, "Géographie", Difficulty.HARD, explanation = "La Chine est le leader mondial de la capacité solaire installée, dépassant largement les autres pays grâce à ses investissements massifs dans les parcs solaires et sa production de panneaux photovoltaïques."),
        Question(9910, "Quel pays a la plus grande capacité géothermale du monde?", listOf("Islande", "Nouvelle-Zélande", "États-Unis", "Indonésie"), 2, "Géographie", Difficulty.HARD, explanation = "Les États-Unis possèdent la plus grande capacité géothermique installée au monde, principalement grâce aux centrales de The Geysers en Californie, le plus vaste complexe géothermique mondial."),
        Question(9911, "Quel est le lac le plus profond d'Europe?", listOf("Lac Onega", "Lac Ladoga", "Lac Baïkal", "Lac Genève"), 2, "Géographie", Difficulty.HARD, explanation = "Le lac Baïkal, situé en Sibérie orientale en Russie, atteint une profondeur maximale de 1 642 mètres, ce qui en fait le lac le plus profond d'Europe et du monde."),
        Question(9912, "Quel est le fleuve le plus long d'Europe?", listOf("Danube", "Volga", "Rhin", "Don"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Volga traverse la Russie sur 3 530 kilomètres avant de se jeter dans la mer Caspienne, ce qui en fait le plus long fleuve d'Europe."),
        Question(9913, "Quel est le plus grand désert d'Asie?", listOf("Gobi", "Taklamakan", "Rub' al Khali", "Arabie"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le désert de Gobi, situé principalement en Mongolie et en Chine, est le plus grand désert d'Asie avec une superficie d'environ 1,3 million de kilomètres carrés."),
        Question(9914, "Quel est le plus grand fleuve d'Asie?", listOf("Gange", "Yangtsé", "Amour", "Iénisseï"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Yangtsé, long d'environ 6 300 km, traverse la Chine d'ouest en est avant de se jeter dans la mer de Chine orientale, ce qui en fait le plus long fleuve d'Asie et le troisième du monde."),
        Question(9915, "Quel est le plus grand lac d'Asie?", listOf("Baïkal", "Aral", "Balkhach", "Issyk-Koul"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le lac d'Aral était autrefois le plus grand lac d'Asie, mais il s'est considérablement asséché depuis les années 1960 en raison de l'irrigation intensive."),
        Question(9916, "Quel est le plus grand archipel d'Asie?", listOf("Hawaï", "Maldives", "Indonésie", "Philippines"), 2, "Géographie", Difficulty.HARD, explanation = "L'Indonésie est le plus grand archipel d'Asie et du monde, avec plus de 17 000 îles, dont les principales sont Java, Sumatra, Bornéo et Sulawesi."),
        Question(9917, "Quel est le plus grand pays d'Océanie?", listOf("Nouvelle-Zélande", "Fidji", "Samoa", "Australie"), 3, "Géographie", Difficulty.EASY, explanation = "L'Australie est le plus grand pays d'Océanie, avec une superficie de près de 7,7 millions de kilomètres carrés, dominant largement la région."),
        Question(9918, "Quel est le plus grand archipel d'Océanie?", listOf("Hawaï", "Polynésie française", "Fiji", "Samoa"), 1, "Géographie", Difficulty.HARD, explanation = "La Polynésie française est le plus grand archipel d'Océanie en superficie maritime, avec 118 îles réparties sur 2,5 millions de km² d'océan."),
        Question(9919, "Quel est le plus grand fleuve d'Amérique du Nord?", listOf("Yukon", "Mississippi", "Mackenzie", "Rio Bravo"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Mississippi est le plus long fleuve d'Amérique du Nord avec ses 3 778 kilomètres, traversant dix États américains avant de se jeter dans le golfe du Mexique."),
        Question(9920, "Quel est le plus grand lac d'Amérique du Nord?", listOf("Lac Michigan", "Lac Supérieur", "Grand Lac de l'Ours", "Grand Lac des Esclaves"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le lac Supérieur est le plus grand lac d'Amérique du Nord par sa superficie, situé entre les États-Unis et le Canada, faisant partie des Grands Lacs."),
        Question(9921, "Quel est le plus grand archipel d'Amérique du Nord?", listOf("Îles de la Reine-Charlotte", "Îles Aléoutiennes", "Archipel du Canada arctique", "Îles Bahamas"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel du Canada arctique, situé dans l'océan Arctique, est le plus vaste archipel d'Amérique du Nord avec plus de 36 000 îles, dont la plus grande est l'île de Baffin."),
        Question(9922, "Quel est le plus grand désert d'Amérique du Nord?", listOf("Désert de Chihuahua", "Désert du Mojave", "Grand Bassin", "Désert de Sonora"), 0, "Géographie", Difficulty.HARD, explanation = "Le désert de Chihuahua s'étend du sud-ouest des États-Unis au nord du Mexique, couvrant environ 450 000 km², ce qui en fait le plus vaste désert d'Amérique du Nord."),
        Question(9923, "Quel est le plus grand fleuve d'Amérique du Sud?", listOf("Amazone", "Orénoque", "Paraná", "São Francisco"), 0, "Géographie", Difficulty.MEDIUM, explanation = "L'Amazone est le plus grand fleuve d'Amérique du Sud en volume d'eau et en longueur, traversant le Brésil, le Pérou et la Colombie."),
        Question(9924, "Quel est le plus grand lac d'Amérique du Sud?", listOf("Lac Titicaca", "Lac Poopó", "Lac Coipasa", "Lac Chinchorro"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le lac Titicaca, situé à la frontière entre le Pérou et la Bolivie, est le plus grand lac d'Amérique du Sud par sa superficie et son volume d'eau. Il est également le plus haut lac navigable du monde, à 3 812 mètres d'altitude."),
        Question(9925, "Quel est le plus grand archipel d'Amérique du Sud?", listOf("Îles Chloé", "Archipel de Juan Fernández", "Îles Galapagos", "Archipel de Tierra del Fuego"), 2, "Géographie", Difficulty.HARD, explanation = "L'archipel des Galapagos, situé dans l'océan Pacifique à l'ouest de l'Équateur, est le plus grand d'Amérique du Sud avec ses 13 îles principales et des dizaines d'îlots."),
        Question(9926, "Quel est le plus grand désert d'Amérique du Sud?", listOf("Désert d'Atacama", "Désert de Sechura", "Pampas", "Cerrado"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le désert d'Atacama, situé au nord du Chili, est le plus grand désert d'Amérique du Sud et l'un des plus arides au monde."),
        Question(9927, "Quel est le point le plus bas du monde?", listOf("Mer Morte", "Lac Baïkal", "Canyon Mariana", "Dépression de Turpan"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint environ 11 034 mètres de profondeur à son point le plus bas, le Challenger Deep, ce qui en fait le point le plus profond de la croûte terrestre."),
        Question(9928, "Quel est le plus long fleuve de Russie?", listOf("Obi", "Léna", "Iénisseï", "Volga"), 2, "Géographie", Difficulty.HARD, explanation = "Long de 5 539 km, l'Iénisseï traverse la Sibérie avant de se jeter dans l'océan Arctique, dépassant la Lena et l'Ob en longueur."),
        Question(9929, "Quel est le plus grand lac de Russie?", listOf("Lac Baïkal", "Ladoga", "Onega", "Vänern"), 0, "Géographie", Difficulty.HARD, explanation = "Le lac Baïkal, situé en Sibérie, est le plus grand lac d'eau douce de Russie par son volume et le plus profond du monde."),
        Question(9930, "Quel est le plus grand fleuve de la Chine?", listOf("Gange", "Yangtsé", "Amour", "Huang He"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Yangtsé, long de 6 300 km, traverse la Chine d'ouest en est pour se jeter dans la mer de Chine orientale. Il est le plus long fleuve d'Asie et le troisième du monde."),
        Question(9931, "Quel est le plus grand fleuve de l'Inde?", listOf("Indus", "Gange", "Brahmapoutre", "Narmada"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Gange est le plus long fleuve de l'Inde avec environ 2 525 km, traversant le nord du pays avant de se jeter dans le golfe du Bengale."),
        Question(9932, "Quel est le plus grand fleuve de l'Afrique?", listOf("Congo", "Niger", "Zambezie", "Nil"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le Nil, avec ses 6 650 kilomètres, traverse l'Afrique de l'Est pour se jeter dans la Méditerranée, dépassant le Congo et le Niger en longueur."),
        Question(9933, "Quel est le plus grand fleuve d'Europe?", listOf("Danube", "Volga", "Dniepr", "Rhin"), 1, "Géographie", Difficulty.HARD, explanation = "La Volga, longue de 3 530 km, traverse la Russie d'ouest en est avant de se jeter dans la mer Caspienne, ce qui en fait le plus long fleuve d'Europe."),
        Question(9934, "Quel est le plus grand fleuve d'Océanie?", listOf("Sepik", "Murray", "Darling", "Finke"), 0, "Géographie", Difficulty.HARD, explanation = "Le Sepik, long de 1 126 km, est le plus long fleuve de Nouvelle-Guinée et d'Océanie, dépassant le Fly en Papouasie-Nouvelle-Guinée."),
        Question(9935, "Quel est le plus grand port du monde par volume?", listOf("Port de Rotterdam", "Port de Singapour", "Port de Shanghai", "Port de Hong Kong"), 2, "Géographie", Difficulty.HARD, explanation = "Le port de Shanghai est le plus grand port du monde en volume de marchandises depuis 2010, dépassant Singapour grâce à l'essor du commerce chinois."),
        Question(9936, "Quel est le plus grand aéroport du monde par nombre de passagers?", listOf("Aéroport de Dubaï", "Aéroport d'Atlanta", "Aéroport de Pékin", "Aéroport de Los Angeles"), 1, "Géographie", Difficulty.HARD, explanation = "L'aéroport international Hartsfield-Jackson d'Atlanta est le plus fréquenté du monde depuis 1998, grâce à sa position de hub majeur pour Delta Air Lines et à la forte demande de transport aérien aux États-Unis."),
        Question(9937, "Quel est le plus grand stade du monde?", listOf("Stade de Michigan", "Stade Beaver", "Stade Tiger", "Stade de Rungrado"), 3, "Géographie", Difficulty.HARD, explanation = "Le Stade de Rungrado, situé à Pyongyang en Corée du Nord, peut accueillir environ 114 000 spectateurs, ce qui en fait le plus grand stade du monde par sa capacité."),
        Question(9938, "Quel est le pont le plus long du monde?", listOf("Pont de la Baie de Hangzhou", "Pont de la Baie de Tokyo", "Viaduc de Millau", "Pont du Roi Fahd"), 0, "Géographie", Difficulty.HARD, explanation = "Le pont de la baie de Hangzhou, en Chine, mesure environ 36 kilomètres, ce qui en fait le plus long pont maritime du monde. Il relie Shanghai à Ningbo depuis son ouverture en 2008."),
        Question(9939, "Quel est le tunnel le plus long du monde?", listOf("Tunnel du Mont-Blanc", "Tunnel de base du Brenner", "Tunnel du Gotthard", "Tunnel du Seikan"), 2, "Géographie", Difficulty.HARD, explanation = "Le tunnel de base du Saint-Gothard, en Suisse, mesure 57 kilomètres, ce qui en fait le plus long tunnel ferroviaire et routier du monde, traversant les Alpes."),
        Question(9940, "Quel est le plus grand château du monde?", listOf("Château de Versailles", "Château de Prague", "Château de Windsor", "Château du Kremlin"), 2, "Géographie", Difficulty.HARD, explanation = "Le château de Windsor, en Angleterre, est le plus grand château habité au monde, avec une superficie de 45 000 mètres carrés."),
        Question(9941, "Quel est le plus grand palais du monde?", listOf("Palais de Versailles", "Palais impérial de Tokyo", "Palais du Kremlin", "Palais royal d'Amritsar"), 1, "Géographie", Difficulty.HARD, explanation = "Le Palais impérial de Tokyo est le plus grand palais du monde en superficie, avec ses 3,41 km², surpassant même la Cité interdite de Pékin."),
        Question(9942, "Quel est le plus grand musée du monde?", listOf("Musée du Louvre", "Musée du Vatican", "Musée de l'Hermitage", "Musée d'art métropolitain"), 2, "Géographie", Difficulty.HARD, explanation = "Le Musée de l'Ermitage à Saint-Pétersbourg est considéré comme le plus grand musée du monde en termes de nombre d'œuvres d'art, avec plus de trois millions de pièces exposées dans un vaste complexe architectural."),
        Question(9943, "Quel est le plus grand temple du monde?", listOf("Temples d'Angkor Vat", "Temple du Mont-Athos", "Temple du Kailasa", "Temple Meenakshi"), 0, "Géographie", Difficulty.HARD, explanation = "Angkor Vat, situé au Cambodge, est considéré comme le plus grand temple du monde en termes de superficie, s'étendant sur plus de 162 hectares."),
        Question(9944, "Quel est le plus grand monastère du monde?", listOf("Monastère du Mont-Athos", "Monastère du Potala", "Monastère Shao Lin", "Monastère de Tebhirine"), 1, "Géographie", Difficulty.HARD, explanation = "Le monastère du Potala, situé à Lhassa au Tibet, est le plus grand du monde avec ses 13 étages et plus de 1000 pièces. Il était la résidence d'hiver du Dalaï-Lama jusqu'en 1959."),
        Question(9945, "Quel est le plus grand mur du monde?", listOf("Muraille de Chine", "Mur d'Hadrien", "Mur de Machu Picchu", "Mur de Jérusalem"), 0, "Géographie", Difficulty.EASY, explanation = "Avec ses 21 196 kilomètres, la Grande Muraille de Chine est la plus longue structure défensive jamais construite par l'homme."),
        Question(9946, "Quel est le plus grand amphithéâtre du monde?", listOf("Colosseum", "Amphithéâtre Flavien", "Amphithéâtre d'Arles", "Amphithéâtre d'El Djem"), 0, "Géographie", Difficulty.HARD, explanation = "Le Colosseum de Rome, avec une capacité estimée à 50 000 spectateurs, est le plus grand amphithéâtre jamais construit dans l'Antiquité."),
        Question(9947, "Quel est le plus grand arc du monde?", listOf("Arc de Triomphe", "Arc de Constantin", "Arc du Millénaire", "Arc de Saint-Louis"), 3, "Géographie", Difficulty.HARD, explanation = "L'Arc de Saint-Louis, situé à Saint-Louis (Missouri), est le plus grand arc du monde avec une hauteur de 192 mètres. Il commémore l'expansion vers l'Ouest des États-Unis."),
        Question(9948, "Quel est le plus grand obélisque du monde?", listOf("Obélisque de Louxor", "Obélisque de Washington", "Obélisque du Vatican", "Obélisque d'Héliopolis"), 3, "Géographie", Difficulty.HARD, explanation = "L'obélisque d'Héliopolis, aussi appelé obélisque de Sésostris Ier, mesure environ 20 mètres de haut et pèse 121 tonnes, ce qui en fait le plus grand obélisque monolithe encore debout au monde."),
        Question(9949, "Quel est le plus grand astrodôme du monde?", listOf("Astrodôme d'Houston", "Dôme du Millénaire", "Biosphère de Montréal", "Dôme du musée Mesco"), 0, "Géographie", Difficulty.HARD, explanation = "L'Astrodôme d'Houston, inauguré en 1965, fut le premier stade entièrement couvert au monde, avec un dôme de 216 mètres de diamètre. Il a longtemps détenu le record du plus grand astrodôme avant d'être surpassé."),
        Question(9950, "Quel est le plus grand aqueduc du monde?", listOf("Aqueduc de Pont-du-Gard", "Aqueduc de Roquefavour", "Aqueduc de Claudio", "Aqueduc de Valens"), 0, "Géographie", Difficulty.HARD, explanation = "L'aqueduc de Pont-du-Gard, situé dans le sud de la France, est le plus haut aqueduc romain encore debout, avec 49 mètres de hauteur, et il faisait partie d'un système de 50 km pour alimenter Nîmes en eau."),
        Question(9951, "Quel est le plus grand phare du monde?", listOf("Phare d'Alexandria", "Phare de Hérodote", "Phare de Eddystone", "Phare de Bishop Rock"), 0, "Géographie", Difficulty.HARD, explanation = "Le phare d'Alexandrie, construit au IIIe siècle av. J.-C., était considéré comme l'une des sept merveilles du monde antique et mesurait environ 130 mètres de haut, ce qui en fait le plus grand phare jamais construit."),
        Question(9952, "Quel est le plus grand cimetière du monde?", listOf("Cimetière de Père-Lachaise", "Cimetière de Calvary", "Cimetière de Najaf", "Cimetière du Mont-Royal"), 2, "Géographie", Difficulty.HARD, explanation = "Le cimetière de Najaf, en Irak, est le plus grand du monde avec plus de six millions de tombes, car il est un lieu saint pour les chiites depuis des siècles."),
        Question(9953, "Quel est le plus grand marché du monde?", listOf("Grand Bazar d'Istanbul", "Bazar de Téhéran", "Marché de Huambo", "Marché de Chatuchak"), 0, "Géographie", Difficulty.HARD, explanation = "Le Grand Bazar d'Istanbul, avec ses 61 rues et plus de 4 000 boutiques, est considéré comme le plus grand marché couvert du monde en termes de superficie et de nombre de commerces."),
        Question(9954, "Quel est le plus grand jardin du monde?", listOf("Jardin de Versailles", "Jardin impérial de Pékin", "Jardin du château de Sanssouci", "Jardin de Kew"), 1, "Géographie", Difficulty.HARD, explanation = "Le Jardin impérial de Pékin, également connu sous le nom de Palais d'Été, s'étend sur environ 290 hectares, ce qui en fait le plus grand jardin du monde par sa superficie."),
        Question(9955, "Quel est le plus grand parc du monde?", listOf("Parc de Yellowstone", "Parc de Denali", "Parc du Groenland du Nord-Est", "Parc de Wrangell-Saint-Elias"), 2, "Géographie", Difficulty.HARD, explanation = "Le Parc national du Groenland du Nord-Est est le plus grand parc du monde, couvrant environ 972 000 km², soit plus que la superficie de la France et de l'Espagne réunies."),
        Question(9956, "Quel est le plus grand zoo du monde?", listOf("Zoo de San Diego", "Zoo du Bronx", "Zoo de Berlin", "Zoo national de Namibie"), 1, "Géographie", Difficulty.HARD, explanation = "Le Zoo du Bronx, à New York, est le plus grand zoo urbain des États-Unis avec plus de 100 hectares et 6 000 animaux, ce qui en fait le plus vaste au monde en termes de superficie."),
        Question(9957, "Quel est le plus grand aquarium du monde?", listOf("Georgia Aquarium", "Aquarium de l'Océan Atlantique", "Aquarium de Dubaï", "Aquarium d'Okinawa"), 0, "Géographie", Difficulty.HARD, explanation = "Le Georgia Aquarium, situé à Atlanta, détient le record du plus grand aquarium du monde avec plus de 38 millions de litres d'eau. Il abrite des milliers d'espèces marines, dont des requins-baleines."),
        Question(9958, "Quel est le plus grand parc thématique du monde?", listOf("Disney World", "Universal Studios", "SeaWorld", "Disneyland"), 0, "Géographie", Difficulty.HARD, explanation = "Disney World, en Floride, s'étend sur environ 121 km², ce qui en fait le plus grand parc thématique du monde en superficie, bien plus vaste que ses concurrents comme Disneyland Paris."),
        Question(9959, "Quel est le plus grand désert d'eau douce du monde?", listOf("Désert du Kalahari", "Désert du Sahara", "Pantanal", "Everglades"), 2, "Géographie", Difficulty.HARD, explanation = "Le Pantanal, situé principalement au Brésil, est la plus grande zone humide tropicale du monde, inondée saisonnièrement par les eaux douces."),
        Question(9960, "Quel est le plus grand écosystème de mangrove du monde?", listOf("Delta du Gange", "Région côtière de Colombie", "Région côtière de Nouvelle-Guinée", "Région côtière d'Australie"), 0, "Géographie", Difficulty.HARD, explanation = "Le delta du Gange, situé entre l'Inde et le Bangladesh, abrite les Sundarbans, la plus vaste forêt de mangrove au monde, couvrant environ 10 000 km²."),
        Question(9961, "Quel est le plus grand écosystème de savane du monde?", listOf("Savane du Serengeti", "Savane du Cerrado", "Savane du Miombo", "Savane du Sahel"), 1, "Géographie", Difficulty.HARD, explanation = "Le Cerrado brésilien est la plus vaste savane du monde, couvrant environ 2 millions de km², soit 22% du territoire du Brésil."),
        Question(9962, "Quel est le plus grand écosystème de forêt tropical du monde?", listOf("Forêt amazo", "Forêt du Congo", "Forêt de l'Asie du Sud-Est", "Forêt du Daintree"), 0, "Géographie", Difficulty.HARD, explanation = "La forêt amazonienne s'étend sur environ 5,5 millions de km² à travers neuf pays d'Amérique du Sud, ce qui en fait le plus vaste écosystème de forêt tropicale au monde."),
        Question(9963, "Quel est le plus grand écosystème de récif corallien du monde?", listOf("Grande Barrière de Corail", "Récif de Ningaloo", "Récif de Mésoamérica", "Récif de Taveuni"), 0, "Géographie", Difficulty.HARD, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres, ce qui en fait le plus vaste système récifal au monde."),
        Question(9964, "Quel est le plus grand écosystème de toundra du monde?", listOf("Toundra de Sibérie", "Toundra du Canada", "Toundra du Groenland", "Toundra de l'Alaska"), 0, "Géographie", Difficulty.HARD, explanation = "La toundra de Sibérie s'étend sur plus de 3 000 kilomètres le long de la côte arctique russe, ce qui en fait la plus vaste étendue de toundra continue au monde."),
        Question(9965, "Quel est le plus grand écosystème de steppe du monde?", listOf("Steppe d'Asie centrale", "Pampas d'Argentine", "Prairie de North America", "Prairie de Mongolie"), 0, "Géographie", Difficulty.HARD, explanation = "La steppe d'Asie centrale, aussi appelée steppe eurasienne, s'étend sur près de 8 000 km de la Hongrie à la Mongolie, ce qui en fait le plus vaste écosystème de steppe au monde."),
        Question(9966, "Quel est le plus grand réserve d'eau douce du monde?", listOf("Lac Baïkal", "Grand Lac des Esclaves", "Lac Tanganyika", "Lac Victoria"), 0, "Géographie", Difficulty.HARD, explanation = "Le lac Baïkal, en Sibérie, contient environ 20% des réserves d'eau douce non gelée de la planète, ce qui en fait le plus grand réservoir d'eau douce liquide au monde."),
        Question(9967, "Quel est le plus grand réserve de pétrole du monde?", listOf("Arabie Saoudite", "Venezuela", "Canada", "Russie"), 0, "Géographie", Difficulty.HARD, explanation = "L'Arabie Saoudite possède les plus grandes réserves de pétrole conventionnel prouvées au monde, estimées à environ 267 milliards de barils, principalement concentrées dans le champ de Ghawar."),
        Question(9968, "Quel est le plus grand réserve de gaz naturel du monde?", listOf("Russie", "Iran", "Qatar", "Turkménistan"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie possède les plus grandes réserves de gaz naturel au monde, estimées à environ 1 688 milliards de mètres cubes, principalement situées en Sibérie occidentale."),
        Question(9969, "Quel est le plus grand réserve de minerai de fer du monde?", listOf("Brésil", "Australie", "Chine", "Inde"), 0, "Géographie", Difficulty.HARD, explanation = "La mine de Carajás, au nord du Brésil, est la plus grande réserve de minerai de fer au monde, avec des milliards de tonnes de minerai à haute teneur."),
        Question(9970, "Quel est le plus grand réserve d'or du monde?", listOf("Australie", "Russie", "Canada", "États-Unis"), 0, "Géographie", Difficulty.HARD, explanation = "L'Australie possède les plus grandes réserves d'or au monde, estimées à environ 8 400 tonnes, principalement concentrées dans la région de Kalgoorlie."),
        Question(9971, "Quel est le plus grand réserve de diamants du monde?", listOf("Russie", "Botswana", "Afrique du Sud", "Angola"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie abrite le plus grand gisement de diamants au monde, situé dans la mine de Mirny en Sibérie, ainsi que le champ de kimberlite de Popigaï, l'un des plus vastes."),
        Question(9972, "Quel est le plus grand réserve de charbon du monde?", listOf("Chine", "Australie", "Inde", "États-Unis"), 3, "Géographie", Difficulty.HARD, explanation = "Les États-Unis possèdent les plus grandes réserves de charbon au monde, estimées à environ 250 milliards de tonnes, principalement dans les bassins des Appalaches, de l'Illinois et du Powder River."),
        Question(9973, "Quel est le plus grand réserve de cuivre du monde?", listOf("Chili", "Pérou", "Zambie", "Congokassai"), 0, "Géographie", Difficulty.HARD, explanation = "Le Chili abrite la plus grande réserve de cuivre au monde, avec la mine d'Escondida, qui est la plus grande mine de cuivre à ciel ouvert. Ce pays domine la production mondiale de cuivre depuis des décennies."),
        Question(9974, "Quel est le plus grand réserve d'uranium du monde?", listOf("Kazakhstan", "Australie", "Canada", "Namibie"), 0, "Géographie", Difficulty.HARD, explanation = "Le Kazakhstan possède les plus grandes réserves d'uranium au monde, avec environ 12% des ressources mondiales, et est le premier producteur depuis 2009."),
        Question(9975, "Quel est le plus grand réserve de cobalt du monde?", listOf("République Démocratique du Congo", "Zambie", "Russie", "Australie"), 0, "Géographie", Difficulty.HARD, explanation = "La République Démocratique du Congo possède environ 70% des réserves mondiales de cobalt, principalement dans la région du Katanga."),
        Question(9976, "Quel est le plus grand réserve de lithium du monde?", listOf("Chili", "Australie", "Argentine", "Chine"), 0, "Géographie", Difficulty.HARD, explanation = "Le Chili abrite le Salar de Atacama, qui contient les plus grandes réserves de lithium connues au monde, représentant environ 40% de la production mondiale."),
        Question(9977, "Quel est le plus grand réserve de terres rares du monde?", listOf("Chine", "États-Unis", "Myanmar", "Russie"), 0, "Géographie", Difficulty.HARD, explanation = "La Chine possède les plus grandes réserves de terres rares au monde, concentrées principalement en Mongolie-Intérieure, et domine leur production et exportation."),
        Question(9978, "Quel est le plus grand réserve de soufre du monde?", listOf("Pologne", "Russie", "Canada", "Irak"), 0, "Géographie", Difficulty.HARD, explanation = "La Pologne possède les plus grandes réserves de soufre au monde, notamment dans la région de Tarnobrzeg, où se trouvait la mine de soufre de Machów, l'une des plus importantes jamais exploitées."),
        Question(9979, "Quel est le plus grand réserve de potasse du monde?", listOf("Canada", "Russie", "Biélorussie", "Israël"), 0, "Géographie", Difficulty.HARD, explanation = "Le Canada possède la plus grande réserve de potasse au monde, située principalement en Saskatchewan, où se trouvent d'immenses gisements souterrains."),
        Question(9980, "Quel est le plus grand réserve de phosphates du monde?", listOf("Maroc", "Chine", "Russie", "États-Unis"), 0, "Géographie", Difficulty.HARD, explanation = "Le Maroc possède les plus grandes réserves mondiales de phosphates, concentrées principalement dans la région de Khouribga. Ces gisements représentent environ 70% des réserves mondiales."),
        Question(9981, "Quel est le plus grand réserve de nickel du monde?", listOf("Indonésie", "Russie", "Australie", "Philippines"), 0, "Géographie", Difficulty.HARD, explanation = "L'Indonésie possède les plus grandes réserves de nickel au monde, principalement situées dans la région de Sulawesi. Ce minerai est essentiel pour la fabrication des batteries de véhicules électriques."),
        Question(9982, "Quel est le plus grand réserve de zinc du monde?", listOf("Australie", "Chine", "Pérou", "Canada"), 0, "Géographie", Difficulty.HARD, explanation = "L'Australie possède les plus grandes réserves de zinc au monde, principalement situées dans la région de Mount Isa et le gisement de McArthur River."),
        Question(9983, "Quel est le plus grand réserve de plomb du monde?", listOf("Australie", "Chine", "Pérou", "États-Unis"), 0, "Géographie", Difficulty.HARD, explanation = "L'Australie possède les plus grandes réserves mondiales de plomb, concentrées principalement dans le gisement de Mount Isa, dans le Queensland."),
        Question(9984, "Quel est le plus grand réserve d'étain du monde?", listOf("Malaisie", "Indonésie", "Chine", "Pérou"), 0, "Géographie", Difficulty.HARD, explanation = "La Malaisie possède les plus grandes réserves d'étain au monde, principalement concentrées dans la région de la vallée de Kinta."),
